insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 1, 'നബി(സ)യുടെ സ്വപ്നങ്ങൾ', 'بَابٌ: فِي رُؤْيَا النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ', 851 from books where volume_id=3 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 2, 'നബി(സ) പാലും വസ്ത്രവും സ്വപ്നം കണ്ടത്', 'بَابٌ: فِي رُؤْيَا النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اللَّبَنَ وَالْقُمُصَ', 852 from books where volume_id=3 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 3, 'നബി(സ) തുലാസും ബക്കറ്റും സ്വപ്നം കണ്ടത്', 'بَابٌ: فِي رُؤْيَا النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْمِيزَانِ وَالدَّلْوِ', 853 from books where volume_id=3 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 4, 'കള്ള പ്രവാചകന്മാരായ മുസൈലിമയെയും അൻസിയെയും നബി(സ) സ്വപ്നം കണ്ടത്', 'بَابٌ: رُؤْيَا النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُسَيْلِمَةَ الْكَذَّابِ وَالْعَنْسِيَ الْكَذَّابِ', 854 from books where volume_id=3 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 5, 'നബി(സ)യെ സ്വപ്നത്തിൽ കാണൽ', 'بَابٌ: رُؤْيَةُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْمَنَامِ', 854 from books where volume_id=3 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 6, 'സത്യവിശ്വാസിയുടെ സ്വപ്നം പ്രവാചകത്വത്തിന്റെ നാൽപത്തിയാറിൽ ഒരംശമാണ്', 'بَابٌ: أَنَّ رُؤْيَا الْمُؤْمِنِ جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنَ النُّبُوَّةِ', 855 from books where volume_id=3 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 7, 'പ്രവാചകത്വം അവസാനിക്കുകയും സന്തോഷവാർത്തകൾ ശേഷിക്കുകയും ചെയ്തു', 'بَابٌ: ذَهَبَتِ النُّبُوَّةُ وَبَقِيَتِ الْمُبَشِّرَاتُ', 856 from books where volume_id=3 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 8, '''ഐഹിക ജീവതത്തിൽ അവർക്ക് സന്തോഷവാർത്തയുണ്ട്'' എന്ന സൂക്തം', 'بَابٌ: قَوْلُهُ: {لَهُمُ الْبُشْرَي فِي الْحَيَاةِ الدُّنْيَا}', 857 from books where volume_id=3 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 9, 'മുസ്ലിം കാണുന്ന നല്ല സ്വപ്നങ്ങൾ', 'بَابٌ: الرُّؤْيَا الصَّالِحَةُ يَرَاهَا الْمُسْلِمُ', 857 from books where volume_id=3 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 10, 'സ്വപ്നം അല്ലാഹുവിൽ നിന്നും പൊയ്കിനാവ് പിശാചിൽ നിന്നുമാണ്', 'بَابٌ: الرُّؤْيَا مِنَ اللهِ وَالْحُلْمُ مِنَ الشَّيْطَانِ', 858 from books where volume_id=3 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 11, 'വെറുക്കുന്ന വല്ലതും കണ്ടാൽ കാവലിനെ ചോദിക്കുകയും താൻ നിലകൊള്ളുന്ന ഭാഗത്ത് നിന്ന് മാറി നിൽക്കുകയും ചെയ്യണം', 'بَابٌ: إِذَا رَأَى مَا يَكْرَهُ فَلْيَتَعَوَّذْ وَلْيَتَحَوَّلْ عَنِ الْجَنْبِ الَّذِي كَانَ عَلَيْهِ', 859 from books where volume_id=3 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 12, 'സ്വപ്ന വ്യാഖ്യാനം', 'بَابٌ: تَعْبِيرُ الرُّؤْيَا', 860 from books where volume_id=3 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 13, 'വ്യാഖ്യാനിക്കപ്പെട്ടാൽ സ്വപ്നം സംഭവിക്കും', 'بَابٌ: الرُّؤْيَا إِذَا عُبِّرَتْ وَقَعَتْ', 864 from books where volume_id=3 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 14, 'പിശാച് ആരെയെങ്കിലും ഉറക്കിൽ ശല്യപ്പെടുത്തിയാൽ അത് ജനങ്ങളോട് പറയരുത്', 'بَابٌ: مَنْ لَعِبَ بِهِ الشَّيْطَانُ فِي مَنَامِهِ فَلَا يُحَدِّثْ بِهِ النَّاسَ', 865 from books where volume_id=3 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 15, 'സ്വപ്നം കണ്ടുവെന്ന് നുണ പറഞ്ഞാൽ', 'بَابٌ: فِي الَّذِي يَكْذِبُ فِي حُلْمِهِ', 865 from books where volume_id=3 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
