insert into books (volume_id, book_no, title_ml, title_ar, start_page) values (3, 17, 'ഗ്രന്ഥകർത്താവിനെക്കുറിച്ച്', null, 1029) on conflict (volume_id, book_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, books.title_ar), start_page=excluded.start_page;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "رَأَيْتُ ذَاتَ لَيْلَةٍ فِيمَايَرَى النَّائِمُ كَأَنَّا فِي دَارِ عُقْبَةَ بْنِ رَافِعٍ، وَأُتِينَا بِرُطَبٍ مِنْ رُطَبِ ابْنِ طَابٍ، فَأَوَّلْتُ أَنَّ الرِّفْعَةَ لَنَا فِي الدُّنْيَا، وَالْعَاقِبَةَ فِي الْآخِرَةِ، وَأَنَّ دِينَنَا قَدْ طَابَ". (م)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു രാത്രി ഞാൻ ഒരു സ്വപ്നം കണ്ടു. നാം ഉഖ്ബതുബിൻ റാഫിഇന്റെ വീട്ടിലാണെന്നതുപോലെയായിരുന്നു അത്. അന്നേരം നമുക്ക് ഒരു മുന്തിയ ഇനം ഈത്തപ്പഴം നൽകപ്പെട്ടു. നമുക്ക് ഐഹികലോകത്ത് ഉന്നതിയും പരലോകത്ത് അന്തിമ വിജയവും ലഭിക്കുമെന്നും നമ്മുടെ ദീൻ പുരോഗമിച്ചിരിക്കുന്നുവെന്നും ഞാൻ ഈ സ്വപ്നത്തെ വ്യാഖ്യാനിച്ചു." (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 851, 851, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رَأَيْتُ فِي الْمَنَامِ أَنِّي أُهَاجِرُ مِنْ مَكَّةَ إِلَى أَرْضٍ بِهَا نَخْلٌ، فَذَهَبَ وَهَلِي إِلَى أَنَّهَا يَمَامَةُ أَوْ هَجَرُ، فَإِذَا هِيَ الْمَدِينَةُ، يَثْرِبُ. وَرَأَيْتُ فِي رُؤْيَايَ هَذِهِ: أَنِّي هَزَزْتُ سَيْفًا فَانْقَطَعَ صَدْرُهُ، فَإِذَا هُوَ مَا أُصِيبَ مِنَ الْمُؤْمِنِينَ يَوْمَ أُحُدٍ. ثُمَّ هَزَزْتُهُ فَعَادَ أَحْسَنَ مَا كَانَ، فَإِذَا هُوَ مَا جَاءَ اللهُ بِهِ مِنَ الْفَتْحِ وَاجْتِمَاعِ الْمُؤْمِنِينَ. وَرَأَيْتُ فِيهَا أَيْضًا بَقَرًا، وَاللهِ خَيْرٌ، فَإِذَا هُمُ النَّفَرُ مِنَ الْمُؤْمِنِينَ يَوْمَ أُحُدٍ، وَإِذَا الْخَيْرُ مَا جَاءَ اللهُ بِهِ مِنَ الْخَيْرِ بَعْدُ، وَثَوَابُ الصِّدْقِ الَّذِي آتَانَا اللهُ بِهِ بَعْدَ يَوْمِ بَدْرٍ". (ق,جه)', 'അബൂമൂസാ(റ): നബി(സ) പറഞ്ഞു: "മക്കയിൽ നിന്ന് ഈത്തപ്പനകളുടെ നാട്ടിലേക്ക് പലായനം ചെയ്യുന്നതായി ഞാൻ സ്വപ്നം കണ്ടു. അത് യമാമയോ ഹജ്റോ ആയിരിക്കുമെന്നാണ് ഞാൻ ആദ്യം ഊഹിച്ചത്. പക്ഷെ, അത് യസ്രിബ് എന്നു പേരുള്ള മദീനയായിരുന്നു. അതേ സ്വപ്നത്തിൽ തന്നെ ഞാനൊരു വാള് ഇളക്കിക്കൊണ്ടിരിക്കുന്നതായും അതിന്റെ നടുഭാഗം പൊട്ടിവീഴുന്നതായും കണ്ടു. ഉഹ്ദിന്റെ ദിവസം വിശ്വാസികൾക്കേറ്റ ബുദ്ധിമുട്ടുകളെ കുറിക്കുന്നതായിരുന്നു അത്. ആ വാളിനെ ഞാൻ വീണ്ടും ഇളക്കുന്നതായും അത് പൂർവ്വോപരി ഭംഗിയുള്ളതായി മാറിയതായും കണ്ടു. അത് അല്ലാഹു നൽകിയ വിജയത്തെയും വിശ്വാസികളുടെ സംഗമത്തെയും കുറിക്കുന്നതായിരുന്നു. അതേ സ്വപ്നത്തിൽ ഞാൻ പശുവിനെയും കണ്ടു. അല്ലാഹു തന്നെ സത്യം, അത് നന്മയായിരുന്നു. അത് ഉഹ്ദ് ദിനത്തിലെ വിശ്വാസികളിൽ ചിലരെ കുറിക്കുന്നതായിരുന്നു. അതിലെ നന്മ, ശേഷം അല്ലാഹു നൽകിയ നന്മകളും ബദ്റ് ദിനത്തിനുശേഷം സത്യസന്ധതക്ക് അല്ലാഹു നമുക്ക് നൽകിയ പ്രതിഫലവുമായിരുന്നു." (ബു,മു,ജ)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 851, 851, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَدْخُلُ عَلَى أُمِّ حَرَامِ بِنْتِ مِلْحَانَ رَضِيَ اللهُ عَنْهَا، وَكَانَتْ تَحْتَ عُبَادَةَ بْنِ الصَّامِتِ، فَدَخَلَ عَلَيْهَا يَوْمًا فَأَطْعَمَتْهُ، وَجَعَلَتْ تَفْلِي رَأْسَهُ، فَنَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ اسْتَيْقَظَ وَهُوَ يَضْحَكُ، قَالَتْ: فَقُلْتُ: مَا يُضْحِكُكَ يَا رَسُولَ اللهِ؟ قَالَ: "نَاسٌ مِنْ أُمَّتِي عُرِضُوا عَلَيَّ غُزَاةً فِي سَبِيلِ اللهِ، يَرْكَبُونَ ثَبَجَ هَذَا الْبَحْرِ، مُلُوكًا عَلَى الْأَسِرَّةِ، أَوْ: مِثْلَ الْمُلُوكِ عَلَى الْأَسِرَّةِ". شَكَّ الرَّاوِي، قَالَتْ: فَقُلْتُ: يَا رَسُولَ اللهِ، ادْعُ اللهَ أَنْ يَجْعَلَنِي مِنْهُمْ، فَدَعَا لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ وَضَعَ رَأْسَهُ ثُمَّ اسْتَيْقَظَ وَهُوَ يَضْحَكُ، فَقُلْتُ: مَا يُضْحِكُكَ يَا رَسُولَ اللهِ؟ قَالَ: "نَاسٌ مِنْ أُمَّتِي عُرِضُوا عَلَيَّ غُزَاةً فِي سَبِيلِ اللهِ". كَمَا قَالَ فِي الْأُولَى، قَالَتْ: فَقُلْتُ: يَا رَسُولَ اللهِ، ادْعُ اللهَ أَنْ يَجْعَلَنِي مِنْهُمْ، قَالَ: "أنتِ مِنَ الْأَوَّلِينَ". فَرَكِبَتِ الْبَحْرَ فِي زَمَانِ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ، فَصُرِعَتْ عَنْ دَابَّتِهَا حِينَ خَرَجَتْ مِنَ الْبَحْرِ، فَهَلَكَتْ. (خ)', 'അനസുബ്നുമാലിക്(റ): നബി(സ) ഉമ്മുഹറാം ബിൻതുമിൽഹാൻ(റ) എന്നവരുടെ അടുത്ത് ഇടക്കിടെ പോകുമായിരുന്നു. അവർ ഉബാദതുബ്നു സ്വാമിത്(റ)വിന്റെ കീഴിലായിരുന്നു. ഒരിക്കൽ നബി(സ) മഹതിയുടെ അടുക്കൽ ചെന്നു. മഹതി നബി(സ)ക്ക് ഭക്ഷണം നൽകി. ശേഷം നബി(സ)യുടെ തലയിൽ പേൻ നോക്കിക്കൊണ്ടിരുന്നു. അതിനിടയിൽ നബി(സ) ഉറങ്ങി. ശേഷം ചിരിച്ചുകൊണ്ട് ഉണർന്നു. മഹതി പറയുന്നു: അപ്പോൾ ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടന്നെന്തിനാണ് ചിരിക്കുന്നത്? റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിൽ നിന്നുള്ള ഒരു കൂട്ടം ആളുകൾ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യുന്നവരായി എന്റെ മുന്നിൽ പ്രത്യക്ഷപ്പെട്ടു. ഈ കടലിന്റെ മുകൾ ഭാഗത്തുകൂടെ ശയ്യകളിലിരിക്കുന്ന രാജാക്കന്മാരായി അല്ലെങ്കിൽ: ശയ്യകളിലിരിക്കുന്ന രാജാക്കന്മാരെപ്പോലെ (നിവേദകന്റെ സംശയം) അവർ യാത്ര ചെയ്യുന്നു." മഹതി പറയുന്നു: അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്നെയും അവരിൽ ഉൾപെടുത്താൻ അവിടന്ന് അല്ലാഹുവിനോട് പ്രാർത്ഥിച്ചാലും. അപ്പോൾ റസൂൽ(സ) മഹതിക്കുവേണ്ടി പ്രാർത്ഥിച്ചു. പിന്നെയും തിരുമേനി(സ) ഉറങ്ങി, ശേഷം ചിരിച്ചുകൊണ്ട് ഉണർന്നു. ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടന്നെന്തിനാണ് ചിരിക്കുന്നത്? റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിൽ നിന്നുള്ള ഒരു കൂട്ടം ആളുകൾ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യുന്നവരായി എന്റെ മുന്നിൽ പ്രത്യക്ഷപ്പെട്ടു." ആദ്യം പറഞ്ഞതു പോലെത്തന്നെ അവിടന്ന് പറഞ്ഞു. മഹതി പറയുന്നു: അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്നെയും അവരിൽ ഉൾപെടുത്താൻ അവിടന്ന് അല്ലാഹുവിനോട് പ്രാർത്ഥിച്ചാലും. അവിടന്ന് പറഞ്ഞു: "നീ ആദ്യ വിഭാഗത്തിൽ പെട്ടവളാണ്." അങ്ങനെ മുആവിയതുബ്നു അബീസുഫ്യാൻ(റ)വിന്റെ കാലത്ത് മഹതി കപ്പലിൽ യാത്രചെയ്യുകയും കടലിൽ നിന്ന് പുറത്തുവന്ന ശേഷം തന്റെ വാഹനത്തിൽ നിന്ന് വീണ് മഹതി വഫാതാവുകയും ചെയ്തു. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, 'നിവേദകന്റെ സംശയം', 851, 852, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ وَرَقَةَ، فَقَالَتْ لَهُ خَدِيجَةُ رَضِيَ اللهُ عَنْهَا: إِنَّهُ كَانَ صَدَّقَكَ، وَلَكِنَّهُ مَاتَ قَبْلَ أَنْ تَظْهَرَ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أُرِيتُهُ فِي الْمَنَامِ وَعَلَيْهِ ثِيَابٌ بَيَاضٌ، وَلَوْ كَانَ مِنْ أَهْلِ النَّارِ لَكَانَ عَلَيْهِ لِبَاسٌ غَيْرَ ذَلِكَ". (ت)', 'ആഇശ(റ): വറഖതിനെക്കുറിച്ച് റസൂൽ(സ) ചോദിച്ചപ്പോൾ ഖദീജ(റ) പറഞ്ഞു: അദ്ദേഹം അങ്ങയിൽ വിശ്വസിച്ചവനായിരുന്നു. പക്ഷെ, അങ്ങ് പ്രത്യക്ഷനാകും മുമ്പ് അദ്ദേഹം മരണപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "വെളുത്ത വസ്ത്രം ധരിച്ചുകൊണ്ട് ഞാൻ അദ്ദേഹത്തെ സ്വപ്നത്തിൽ കണ്ടു. അദ്ദേഹം നരകാവകാശിയാണെങ്കിൽ അദ്ദേഹം മറ്റേതെങ്കിലും വസ്ത്രമായിരിക്കും ധരിക്കുക." (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 852, 852, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "بَيْنَمَا أَنَا نَائِمٌ إِذْ أُتِيتُ بِقَدَحِ لَبَنٍ، فَشَرِبْتُ مِنْهُ، ثُمَّ أَعْطَيْتُ فَضْلِي عُمَرَ بْنَ الْخَطَّابِ". قَالُوا: فَمَا أَوَّلْتَهُ يَا رَسُولَ اللهِ؟ قَالَ: "الْعِلْمَ". صَحِيحٌ. (ق,ت)', 'ഇബ്നുഉമർ(റ): നബി(സ) ഇപ്രകാരം പറയുന്നതായി ഞാൻ കേട്ടു: "ഞാൻ ഉറങ്ങിക്കൊണ്ടിരിക്കെ ഒരു പാത്രം പാൽ എന്റെയടുത്തേക്ക് കൊണ്ടുവരപ്പെട്ടു. ഞാൻ അതിൽ നിന്ന് കുടിക്കുകയും ബാക്കിയുള്ളത് ഉമറുബ്നുൽ ഖത്താബ്(റ)വിന് നൽകുകയും ചെയ്തു." അവർ ചോദിച്ചു: റസൂലേ, എപ്രകാരമാണ് അതിനെ അങ്ങ് വ്യാഖ്യാനിക്കുന്നത്? നബി(സ) പറഞ്ഞു: "വിജ്ഞാനമായിട്ടാണ്." (ബു,മു,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 852, 853, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ، عَنْ بَعْضِ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بَيْنَمَا أَنَا نَائِمٌ رَأَيْتُ النَّاسَ يُعْرَضُونَ عَلَيَّ وَعَلَيْهِمْ قُمُصٌ، مِنْهَا مَا يَبْلُغُ الثُّدِيَّ، وَمِنْهُ مَا يَبْلُغُ أَسْفَلَ مِنْ ذَلِكَ، فَعُرِضَ عَلَيَّ عُمَرُ وَعَلَيْهِ قَمِيصٌ يَجُرُّهُ". قَالُوا: فَمَا أَوَّلْتَهُ يَا رَسُولَ اللهِ؟ قَالَ: "الدِّينَ". عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمَعْنَاهُ. (ق,ت,ن)', 'നബി(സ)യുടെ ചില അനുചരരിൽ നിന്ന് അബൂഉമാമതുബ്നു സഹ്ലുബ്നു ഹുനൈഫ്(റ): നബി(സ) പറഞ്ഞു: "ഞാൻ ഉറങ്ങിക്കൊണ്ടിരിക്കെ വസ്ത്രങ്ങൾ ധരിച്ച കുറേ പേരെ എനിക്ക് കാണിക്കപ്പെട്ടു. നെഞ്ച് വരെ എത്തുന്ന വസ്ത്രങ്ങൾ അതിലുണ്ട്. അതിനേക്കാൾ താഴെയെത്തുന്ന വസ്ത്രങ്ങളുമുണ്ട്. അപ്പോൾ നിലത്തിട്ട് വലിക്കുന്ന വസ്ത്രം ധരിച്ചവനായിട്ട് ഉമറിനെ എനിക്ക് കാണിക്കപ്പെട്ടു." അവർ (സ്വഹാബികൾ) ചോദിച്ചു: റസൂലേ, അങ്ങ് എപ്രകാരമാണ് അതിനെ വ്യാഖ്യാനിച്ചത്? നബി(സ) പറഞ്ഞു: "മതമായിട്ടാണ്." അബൂസഇൗദ്(റ)വിൽ നിന്നും നബി(സ)യെക്കുറിച്ച് ഇതിന്റെ അർത്ഥത്തിലുള്ള സംഭവം നിവേദനം ചെയ്യപ്പെട്ടിട്ടുണ്ട്. (ബു,മു,തു,ന)', 'أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ، عَنْ بَعْضِ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ', 'നബി(സ)യുടെ ചില അനുചരരിൽ നിന്ന് അബൂഉമാമതുബ്നു സഹ്ലുബ്നു ഹുനൈഫ്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 853, 853, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ ذَاتَ يَوْمٍ: "مَنْ رَأَى مِنْكُمْ رُؤْيَا". فَقَالَ رَجُلٌ: أَنَا رَأَيْتُ كَأَنَّ مِيزَانًا نَزَلَ مِنَ السَّمَاءِ، فَوُزِنْتَ أَنْتَ وَأَبُو بَكْرٍ، فَرَجَحْتَ أَنْتَ بِأَبِي بَكْرٍ، وَوُزِنَ أَبُو بَكْرٍ وَعُمَرُ، فَرَجَحَ أَبُو بَكْرٍ، وَوُزِنَ عُمَرُ وَعُثْمَانُ فَرَجَحَ عُمَرُ، ثُمَّ رُفِعَ الْمِيزَانُ. فَرَأَيْنَا الْكَرَاهِيَةَ فِي وَجْهِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. حَسَنٌ صَحِيحٌ. (د,ت)', 'അബൂബക്റ(റ): ഒരു ദിവസം നബി(സ) പറഞ്ഞു: "നിങ്ങളാരെങ്കിലും വല്ല സ്വപ്നവും കണ്ടിട്ടുണ്ടോ?" ഒരാൾ പറഞ്ഞു: തുലാസ് (മീസാൻ) ആകാശത്തുനിന്ന് ഇറക്കപ്പെട്ടത് പോലെ ഞാൻ കണ്ടു. എന്നിട്ട് അങ്ങും അബൂബക്കർ(റ)വും അതിൽ തൂക്കപ്പെട്ടു. അപ്പോൾ അബൂബക്കർ(റ)വിനേക്കാൾ അങ്ങ് കനം തൂങ്ങി. പിന്നെ അബൂബക്കർ(റ)വും ഉമർ(റ)വും തൂക്കപ്പെട്ടപ്പോൾ അബൂബക്കർ(റ) കനം തൂങ്ങി. ശേഷം ഉമർ(റ)വും ഉസ്മാൻ(റ)വും തൂക്കപ്പെട്ടു. അപ്പോൾ ഉമർ(റ) കനം തൂങ്ങി. ശേഷം തുലാസ് ഉയർത്തപ്പെട്ടു. ഇത് കേട്ടപ്പോൾ റസൂൽ(സ)യുടെ മുഖത്ത് ഞങ്ങൾ വെറുപ്പ് കണ്ടു. (ദ,തു)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 853, 853, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: عَنْ رُؤْيَا النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَبَا بَكْرٍ وَعُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: "رَأَيْتُ النَّاسَ اجْتَمَعُوا، فَنَزَعَ أَبُو بَكْرٍ ذَنُوبًا أَوْ ذَنُوبَيْنِ، فِيهِ ضَعْفٌ وَاللهُ يَغْفِرُ لَهُ، ثُمَّ قَامَ عُمَرُ فَنَزَعَ فَاسْتَحَالَتْ غَرْبًا، فَلَمْ أَرَ عَبْقَرِيًّا يَفْرِي فَرِيَهُ، حَتَّى ضَرَبَ النَّاسُ بِعَطَنٍ". صَحِيحٌ. (ق)', 'നബി(സ), അബൂബക്കർ(റ)വിനെയും ഉമർ(റ)വിനെയും സ്വപ്നം കണ്ടതിനെക്കുറിച്ച് അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "ജനങ്ങൾ ഒരുമിച്ച് കൂടിയതായി ഞാൻ കണ്ടു. അപ്പോൾ അബൂബക്കർ നിറഞ്ഞ ഒന്നോ രണ്ടോ ബക്കറ്റ് വലിച്ചെടുത്തു. അബൂബക്കറിൽ അശക്തതയുണ്ടായിരുന്നു. അദ്ദേഹത്തിന് അല്ലാഹു പൊറുത്തുകൊടുക്കട്ടെ. ശേഷം ഉമർ എഴുന്നേറ്റ് ബക്കറ്റ് വലിച്ചു. അപ്പോഴത് വലിയ ബക്കറ്റായി മാറി. അദ്ദേഹത്തെപ്പോലെ ആ ജോലി ചെയ്യുന്ന ഒരു ശക്തനേയും ഞാൻ കണ്ടില്ല. അങ്ങനെ ജനങ്ങൾ ജലസംഭരണിയുണ്ടാക്കി തമ്പടിച്ചു." (ബു,മു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'നബി(സ), അബൂബക്കർ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 853, 853, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، قَالَ: قَدِمَ مُسَيْلِمَةُ الْكَذَّابُ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ، فَجَعَلَ يَقُولُ: إِنْ جَعَلَ لِي مُحَمَّدٌ الْأَمْرَ مِنْ بَعْدِهِ تَبِعْتُهُ. فَقَدِمَهَا فِي بَشَرٍ كَثِيرٍ مِنْ قَوْمِهِ، فَأَقْبَلَ إِلَيْهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَمَعَهُ ثَابِتُ بْنُ قَيْسِ بْنِ شَمَّاسٍ، وَفِي يَدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قِطْعَةُ جَرِيدَةٍ، حَتَّى وَقَفَ عَلَى مُسَيْلِمَةَ فِي أَصْحَابِهِ، قَالَ: "لَوْ سَأَلْتَنِي هَذِهِ الْقِطْعَةَ مَا أَعْطَيْتُكَهَا، وَلَنْ أَتَعَدَّى أَمْرَ اللهِ فِيكَ، وَلَئِنْ أَدْبَرْتَ لَيَعْقِرَنَّكَ اللهُ، وَإِنِّي لَأَرَاكَ الَّذِي أُرِيتُ فِيكَ مَا أُرِيتُ، وَهَذَا ثَابِتٌ يُجِيبُكَ عَنِّي". ثُمَّ انْصَرَفَ عَنْهُ، فَقَالَ ابْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: فَسَأَلْتُ عَنْ قَوْلِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّكَ أَرَى الَّذِي أُرِيتُ فِيكَ مَا أُرِيتُ". فَأَخْبَرَنِي أَبُو هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بَيْنَا أَنَا نَائِمٌ رَأَيْتُ فِي يَدَيَّ سِوَارَيْنِ مِنْ ذَهَبٍ، فَأَهَمَّنِي شَأْنُهُمَا، فَأُوحِيَ إِلَيَّ فِي الْمَنَامِ: أَنِ انْفُخْهُمَا، فَنَفَخْتُهُمَا فَطَارَا، فَأَوَّلْتُهُمَا كَذَّابَيْنِ يَخْرُجَانِ مِنْ بَعْدِي، فَكَانَ أَحَدُهُمَا الْعَنْسِيَ صَاحِبَ صَنْعَاءَ، وَالْآخَرُ مُسَيْلِمَةَ صَاحِبَ الْيَمَامَةِ". (ق,ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)യുടെ കാലത്ത് മുസൈലിമതുൽ കദ്ദാബ് മദീനയിലേക്ക് വന്നു. മുഹമ്മദ്(സ)ക്ക് ശേഷം കാര്യങ്ങൾ എന്നെ ഏൽപിക്കുകയാണെങ്കിൽ ഞാനവനെ പിൻപറ്റുമെന്ന് അവൻ പറഞ്ഞുകൊണ്ടിരുന്നു. തന്റെ സമൂഹത്തിലെ നിരവധിപേർക്കൊപ്പമായിരുന്നു അവൻ മദീനയിലേക്ക് വന്നിരുന്നത്. നബി(സ) സാബിതുബ്നു ഖൈസുബ്നു ശമ്മാസ്(റ)വിന്റെ കൂടെ അവന്റെയടുത്തേക്ക് പോയി. നബി(സ)യുടെ കയ്യിൽ ഒരു ഈത്തപ്പനക്കഷ്ണമുണ്ടായിരുന്നു. നബി(സ) മുസൈലിമയുടെയും അനുചരൻമാരുടെയും അടുത്ത് നിന്നു, എന്നിട്ട് പറഞ്ഞു: "ഈ ഈത്തപ്പനക്കഷ്ണം ചോദിച്ചാൽ പോലും നിനക്ക് ഞാനിത് തരില്ല. അല്ലാഹുവിന്റെ കാര്യത്തിൽ നിനക്ക് വേണ്ടി ഞാൻ അതിരുകടക്കുകയില്ല. നീ പിന്തിരിഞ്ഞുപോയാൽ അല്ലാഹു നിന്നെ നശിപ്പിക്കുക തന്നെ ചെയ്യും. മുമ്പുതന്നെ എനിക്ക് പൂർണ്ണമായി വിവരമറിയിക്കപ്പെട്ട വ്യക്തിയായി നിന്നെ ഞാൻ കാണുന്നു. ഈ സാബിത് എനിക്ക് പകരം നിനക്ക് മറുപടി നൽകും." ശേഷം നബി(സ) അവിടെ നിന്ന് മടങ്ങി. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: "മുമ്പ്തന്നെ എനിക്ക് പൂർണ്ണമായി വിവരമറിയിക്കപ്പെട്ട വ്യക്തിയാണ് നീ" എന്ന നബി(സ)യുടെ വാക്കിനെപ്പറ്റി ഞാൻ ചോദിച്ചു. അപ്പോൾ അബൂഹുറൈറ(റ) എന്നോട് പറഞ്ഞു: നബി(സ) പറയുകയുണ്ടായി: "ഞാൻ ഉറങ്ങിക്കൊണ്ടിരിക്കെ എന്റെ കയ്യിൽ രണ്ട് സ്വർണ വളകൾ കണ്ടു. അവയുടെ കാര്യം എന്നെ വളരെയേറെ ദുഃഖിപ്പിച്ചു. അപ്പോൾ അവരണ്ടിനേയും ഊതിക്കളയാൻ എനിക്ക് സ്വപ്നത്തിൽ ദൈവബോധനം (വഹ്യ്) ലഭിച്ചു. ഞാൻ അവയെ ഊതുകയും അവ പാറിപ്പോകുകയും ചെയ്തു. എനിക്ക് ശേഷം പുറപ്പെടുന്ന രണ്ട് കള്ളവാദികളായി ഞാൻ അവയെ വ്യാഖ്യാനിച്ചു. അവരിലൊരുത്തൻ സൻആളകാരനായ അൻസിയും മറ്റൊരുത്തൻ യമാമക്കാരനായ മുസൈലിമയുമായിരുന്നു." (ബു,മു,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 854, 854, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي فِي الْيَقَظَةِ، فَإِنَّ الشَّيْطَانَ لَا يَتَمَثَّلُ عَلَى صُورَتِي". (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): പ്രവാചകർ(സ) പറഞ്ഞു: "എന്നെ സ്വപ്നത്തിൽ കണ്ടവൻ ഉണയർച്ചയിൽ തന്നെയാണ് എന്നെ കണ്ടിരിക്കുന്നത്. കാരണം പിശാച് എന്റെ കോലത്തിൽ രൂപം പ്രാപിക്കുകയില്ല." (തു,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 854, 855, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي، إِنَّهُ لَا يَنْبَغِي لِلشَّيْطَانِ أَنْ يَتَمَثَّلَ فِي صُورَتِي". (م,جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്നെ സ്വപ്നത്തിൽ ദർശിച്ചവൻ എന്നെത്തന്നെയാണ് കണ്ടിരിക്കുന്നത്. കാരണം നിശ്ചയം പിശാചിന് എന്റെ കോലത്തിൽ രൂപം പ്രാപിക്കാൻ സാധിക്കുകയില്ല." (മു,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 855, 855, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ رَآنِي فِي الْمَنَامِ فَكَأَنَّمَا رَآنِي فِي الْيَقَظَةِ، إِنَّ الشَّيْطَانَ لَا يَسْتَطِيعُ أَنْ يَتَمَثَّلَ بِي". (جه)', 'അബൂജുഹൈഫ(റ): പ്രവാചകർ(സ) പറഞ്ഞു: "എന്നെ സ്വപ്നത്തിൽ കണ്ടവൻ ഉണർച്ചയിൽ എന്നെ കണ്ടവനെപ്പോലെയാണ്. കാരണം പിശാചിന് എന്റെ രൂപം പ്രാപിക്കാൻ സാധിക്കുകയില്ല." (ജ)', 'أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 855, 855, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ رَآنِي فِي الْمَنَامِ فَسَيَرَانِي فِي الْيَقَظَةِ، أَوْ: لَكَأَنَّمَا رَآنِي فِي الْيَقَظَةِ، لَا يَتَمَثَّلُ الشَّيْطَانُ بِي". وَقَالَ: فَقَالَ أَبُو سَلَمَةَ: قَالَ أَبُو قَتَادَةَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ رَآنِي فَقَدْ رَأَى الْحَقَّ". (ق,ت,جه)', 'അബൂഹുറൈറ(റ): പ്രവാചകർ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "എന്നെ സ്വപ്നം കണ്ടവൻ ഉണർച്ചയിൽ എന്നെ കാണുന്നതാണ്. അല്ലെങ്കിൽ: അവൻ എന്നെ ഉണർച്ചയിൽ കണ്ടതു പേലെയാണ്. പിശാച് എന്റെ രൂപം പ്രാപിക്കുകയില്ല." അബൂസലമ(റ) പറയുന്നു: അബൂഖതാദ(റ) പറഞ്ഞു: പ്രവാചകർ(സ) പറഞ്ഞു: "എന്നെ സ്വപ്നം കണ്ടവൻ സത്യമായ സ്വപ്നമാണ് ദർശിച്ചിരിക്കുന്നത്." (ബു,മു,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 855, 855, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ رَآنِي فَقَدْ رَأَى الْحَقَّ، فَإِنَّ الشَّيْطَانَ لَا يَتَكَوَّنُنِي". (خ)', 'അബൂസഇൗദിൽ ഖുദ്രി(റ): പ്രവാചകർ(സ) പറയുന്നതായി അദ്ദേഹം കേട്ടു: "എന്നെ സ്വപ്നം കണ്ടവൻ സത്യമായ സ്വപ്നമാണ് കണ്ടിരിക്കുന്നത്. കാരണം പിശാച് എന്റെ രൂപം പ്രാപികക്കുകയില്ല." (ബു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദിൽ ഖുദ്രി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 855, 855, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا اقْتَرَبَ الزَّمَانُ لَمْ تَكَدْ رُؤْيَا الْمُسْلِمِ تَكْذِبُ، وَأَصْدَقُهُمْ رُؤْيًا أَصْدَقُهُمْ حَدِيثًا، وَرُؤْيَا الْمُسْلِمِ جُزْءٌ مِنْ خَمْسَةٍ وَأَرْبَعِينَ جُزْءاً مِنَ النُّبُوَّةِ، وَالرُّؤْيَا ثَلَاثَةٌ: فَالرُّؤْيَا الصَّالِحَةُ بُشْرَى مِنَ اللهِ، وَالرُّؤْيَا تَحْزِينٌ مِنَ الشَّيْطَانِ، وَرُؤْيَا مِمَّا يُحَدِّثُ الْمَرْءُ نَفْسَهُ، فَإِنْ رَأَى أَحَدُكُمْ مَا يَكْرَهُ فَلْيَقُمْ فَلْيُصَلِّ – وَفِي رِوَايَةٍ: فَلْيَتْفُلْ – وَلَا يُحَدِّثْ بِهَا النَّاسَ". قَالَ: "وَأُحِبُّ الْقَيْدَ وَأَكْرَهُ الْغُلَّ، وَالْقَيْدُ ثَبَاتٌ فِي الدِّينِ". فَلَا أَدْرِي هُوَ فِي الْحَدِيثِ أَمْ قَالَهُ ابْنُ سِيرِينَ. (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അന്ത്യനാൾ അടുത്താൽ വിശ്വാസിയുടെ സ്വപ്നം കളവാകുകയില്ല. അവരിൽ ഏറ്റവും സത്യസന്ധമായ സ്വപ്നം കാണുക ഏറ്റവും സത്യസന്ധമായി സംസാരിക്കുന്നവൻ ആയിരിക്കും. മുസ്ലിമിന്റെ സ്വപ്നം നുബുവ്വത്തിന്റെ നാൽപത്തിയഞ്ചിൽ ഒരംശമാണ്. സ്വപ്നം മൂന്നു വിധമുണ്ട്. അല്ലാഹുവിൽ നിന്ന് സന്തോഷവാർത്തയായി വരുന്ന നല്ല സ്വപ്നം, പിശാചിൽ നിന്നുള്ള ദുഃഖിപ്പിക്കുന്ന സ്വപ്നം, മനുഷ്യൻ സ്വന്തത്തോട് സംസാരിക്കുന്ന സ്വപ്നം. അതിനാൽ നിങ്ങളാരെങ്കിലും വെറുക്കുന്ന സ്വപ്നം കണ്ടാൽ അവൻ എഴുന്നേറ്റ് നിസ്കരിച്ചുകൊള്ളട്ടെ - മറ്റൊരു നിവേദനത്തിൽ: തുപ്പിക്കൊള്ളട്ടെ എന്നാണുള്ളത് - ജനങ്ങളോട് ആ സ്വപ്നം അറിയിക്കരുത്." നബി(സ) പറഞ്ഞു: "ഉറങ്ങുന്ന സന്ദർഭത്തിൽ സ്ഥിരമായിരിക്കലിനെ ഞാൻ ഇഷ്ടപ്പെടുകയും ബന്ധിതനായിരിക്കലിനെ വെറുക്കുകയും ചെയ്യുന്നു. ഖൈദ് എന്നാൽ ദീനിൽ സ്ഥിരമാകലാണ്." അക്കാര്യം ഹദീസിലുണ്ടോ അതോ ഇബ്നുസീരീൻ(റ) പറഞ്ഞതാണോ എന്ന് എനിക്കറിയില്ല. (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 855, 856, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=15 and h.hadith_no=15), 1, 'وَفِي رِوَايَةٍ: فَلْيَتْفُلْ – وَلَا يُحَدِّثْ بِهَا النَّاسَ". قَالَ: "وَأُحِبُّ الْقَيْدَ وَأَكْرَهُ الْغُلَّ، وَالْقَيْدُ ثَبَاتٌ فِي الدِّينِ". فَلَا أَدْرِي هُوَ فِي الْحَدِيثِ أَمْ قَالَهُ ابْنُ سِيرِينَ. (ق,د,ت,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: തുപ്പിക്കൊള്ളട്ടെ എന്നാണുള്ളത് - ജനങ്ങളോട് ആ സ്വപ്നം അറിയിക്കരുത്." നബി(സ) പറഞ്ഞു: "ഉറങ്ങുന്ന സന്ദർഭത്തിൽ സ്ഥിരമായിരിക്കലിനെ ഞാൻ ഇഷ്ടപ്പെടുകയും ബന്ധിതനായിരിക്കലിനെ വെറുക്കുകയും ചെയ്യുന്നു. ഖൈദ് എന്നാൽ ദീനിൽ സ്ഥിരമാകലാണ്." അക്കാര്യം ഹദീസിലുണ്ടോ അതോ ഇബ്നുസീരീൻ(റ) പറഞ്ഞതാണോ എന്ന് എനിക്കറിയില്ല. (ബു,മു,ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا اقْتَرَبَ الزَّمَانُ لَمْ تَكَدْ رُؤْيَا الْمُؤْمِنِ تَكْذِبُ، وَرُؤْيَا الْمُؤْمِنِ جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنَ النُّبُوَّةِ. وَمَا كَانَ مِنَ النُّبُوَّةِ فَإِنَّهُ لَا يَكْذِبُ". (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അന്ത്യനാൾ അടുത്താൽ വിശ്വാസിയുടെ സ്വപ്നം കളവാകുകയില്ല. വിശ്വാസിയുടെ സ്വപ്നം നുബുവ്വത്തിന്റെ നാൽപത്തിയാറിൽ ഒരു അംശമാണ്. നുബുവ്വത്തിൽ പെട്ട കാര്യം കളവാകുകയില്ല." (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 856, 856, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ "إِنَّ الرِّسَالَةَ وَالنُّبُوَّةَ قَدِ انْقَطَعَتْ، فَلَا رَسُولَ بَعْدِي وَلَا نَبِيَّ". قَالَ: فَشَقَّ ذَلِكَ عَلَى النَّاسِ، فَقَالَ: "لَكِنِ الْمُبَشِّرَاتُ". قَالُوا: يَا رَسُولَ اللهِ، وَمَا الْمُبَشِّرَاتُ؟ قَالَ: "رُؤْيَا الْمُسْلِمِ، وَهِيَ جُزْءٌ مِنْ أَجْزَاءِ النُّبُوَّةِ". حَسَنٌ صَحِيحٌ. (ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "പ്രവാചകത്വവും (നുബുവ്വത്) ദൗത്യനിർവ്വഹണവും (രിസാലത്) അവസാനിച്ചിരിക്കുന്നു. അതിനാൽ എന്റെ ശേഷം ഒരു നബിയോ റസൂലോ ഇല്ല." നിവേദകൻ പറഞ്ഞു: ഇത് ജനങ്ങൾക്ക് പ്രയാസകരമായി തോന്നിയപ്പോൾ നബി(സ) പറഞ്ഞു: "പക്ഷേ, സന്തോഷവാർത്തകൾ ശേഷിക്കും." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്താണ് സന്തോഷവാർത്തകൾ? നബി(സ) പറഞ്ഞു: "അത് മുസ്ലിമിന്റെ സ്വപ്നമാണ്. ആ സ്വപ്നം പ്രവാചകത്വത്തിന്റെ ഒരു ഭാഗമാണ്." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 856, 856, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أُمِّ كُرْزٍ الْكَعْبِيَّةِ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "ذَهَبَتِ النُّبُوَّةُ وَبَقِيَتِ الْمُبَشِّرَاتُ". (م,جه)', 'ഉമ്മുകുർസുനിൽ കഅ്ബിയ്യ(റ): റസൂൽ(സ) പറയുന്നു: "നുബുവ്വത് (പ്രവാചകത്വം) പോയി, സന്തോഷവാർത്തകൾ അവശേഷിച്ചു." (മു,ജ)', 'أُمِّ كُرْزٍ الْكَعْبِيَّةِ', 'ഉമ്മുകുർസുനിൽ കഅ്ബിയ്യ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 856, 856, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَشَفَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ السِّتَارَةَ فِي مَرَضِهِ، وَالصُّفُوفُ خَلْفَ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ، فَقَالَ: "أَيُّهَا النَّاسُ، إِنَّهُ لَمْ يَبْقَ مِنْ مُبَشِّرَاتِ النُّبُوَّةِ إِلَّا الرُّؤْيَا الصَّالِحَةُ، يَرَاهَا الْمُسْلِمُ أَوْ تُرَى لَهُ". (م,د,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) രോഗിയായിരിക്കുമ്പോൾ ജനങ്ങൾ അബൂബക്കർ(റ)വിന്റെ പിന്നിൽ അണിനിരന്നിരിക്കെ നബി(സ) മറ നീക്കി, എന്നിട്ട് പറഞ്ഞു: "അല്ലയോ ജനങ്ങളേ, നിശ്ചയം ഒരു മുസ്ലിം കാണുകയോ അവന് കാണിക്കപ്പെടുകയോ ചെയ്യുന്ന നല്ല സ്വപ്നങ്ങളല്ലാതെ നുബുവ്വതിന്റെ സന്തോഷവാർത്തകളിൽ നിന്ന് ഒന്നും ശേഷിച്ചിട്ടില്ല." (മു,ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 856, 856, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَمْ يَبْقَ مِنَ النُّبُوَّةِ إِلَّا الْمُبَشِّرَاتُ". قَالُوا: وَمَا الْمُبَشِّرَاتُ؟ قَالَ: "الرُّؤْيَا الصَّالِحَةُ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നുബുവ്വതിൽ നിന്ന് സന്തോഷ വാർത്തകൾ മാത്രമാണ് ശേഷിച്ചിട്ടുള്ളത്." അവർ ചോദിച്ചു: എന്താണ് ആ സന്തോഷ വാർത്തകൾ? റസൂൽ(സ) പറഞ്ഞു: "അത് നല്ല സ്വപ്നങ്ങളാണ്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 857, 857, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَأَلَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ قَوْلِ اللهِ تَعَالَى: {لَهُمُ الْبُشْرَى فِي الْحَيَاةِ الدُّنْيَا} فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا سَأَلَنِي عَنْهَا أَحَدٌ غَيْرُكَ مُنْذُ أُنْزِلَتْ، هِيَ الرُّؤْيَا الصَّالِحَةُ، يَرَاهَا الْمُسْلِمُ أَوْ تُرَى لَهُ". (ت,جه)', 'അബുദ്ദർദാഅ്(റ): ''ഐഹിക ജീവിതത്തിൽ അവർക്ക് സന്തോഷവാർത്തയുണ്ട്'' എന്ന ദൈവിക വചനത്തെക്കുറിച്ച് അദ്ദേഹം നബി(സ)യോട് ചോദിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അത് അവതരിക്കപ്പെട്ടതു മുതൽ നീയല്ലാതെ ഒരാളും അതിനെക്കുറിച്ച് എന്നോട് ചോദിച്ചിട്ടില്ല. മുസ്ലിം കാണുന്ന അല്ലെങ്കിൽ അവന് കാണിക്കപ്പെടുന്ന സത്യസന്ധമായ സ്വപ്നമാണത്." (തു,ജ)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 857, 857, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَصْدَقُ الرُّؤْيَا بِالْأَسْحَارِ". (ت)', 'അബൂസഇൗദ്(റ): നബി(സ) പറഞ്ഞു: "അത്താഴ സമയങ്ങളിലെ സ്വപ്നമാണ് ഏറ്റവും സത്യസന്ധമായവ." (തു)', 'أَبِي سَعِيدٍ', 'അബൂസഇൗദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 857, 857, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الرُّؤْيَا الْحَسَنَةُ – مِنَ الرَّجُلِ الصَّالِحِ – جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنَ النُّبُوَّةِ". (خ,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "സൽവൃത്തനിൽ നിന്നുള്ള നല്ല സ്വപ്നം നുബുവ്വത്തിന്റെ നാൽപ്പത്തിയാറിൽ ഒരംശമാണ്." (ബു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 857, 857, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رُؤْيَا الرَّجُلِ الْمُسْلِمِ الصَّالِحِ جُزْءٌ مِنْ سَبْعِينَ جُزْءًا مِنَ النُّبُوَّةِ". [في سنده ضعيف] (جه)', 'അബൂസഇൗദുൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "നല്ലവനായ മുസ്ലിമിന്റെ സ്വപ്നം നുബുവ്വതിന്റെ എഴുപതിൽ ഒരു അംശമാണ്." ഇതിന്റെ പരമ്പരയിൽ ഒരു ബലഹീനനുണ്ട്. (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദുൽ ഖുദ്രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في سنده ضعيف', null, 857, 857, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الرُّؤْيَا الصَّالِحَةُ جُزْءٌ مِنْ سَبْعِينَ جُزْءًا مِنَ النُّبُوَّةِ". (م,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "സത്യസന്ധമായ സ്വപ്നം നുബുവ്വതിന്റെ എഴുപതിൽ ഒരു ഭാഗമാണ്." (മു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 857, 857, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ أَبِي سَلَمَةَ قَالَ: إِنْ كُنْتُ لَأَرَى الرُّؤْيَا تُمْرِضُنِي، قَالَ: فَلَقِيتُ أَبَا قَتَادَةَ فَقَالَ: وَأَنَا إِنْ كُنْتُ لَأَرَى الرُّؤْيَا فَتُمْرِضُنِي، حَتَّى سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ الرُّؤْيَا الصَّالِحَةَ مِنَ اللهِ، فَإِذَا رَأَى أَحَدُكُمْ مَا يُحِبُّ فَلَا يُحَدِّثْ بِهَا إِلَّا مَنْ يُحِبُّ. وَإِذَا رَأَى مَا يَكْرَهُ فَلْيَتْفُلْ عَنْ يَسَارِهِ ثَلَاثًا، وَلْيَتَعَوَّذْ بِاللهِ مِنْ شَرِّ الشَّيْطَانِ وَشَرِّهَا، وَلَا يُحَدِّثْ بِهَا أَحَدًا، فَإِنَّهَا لَنْ تَضُرَّهُ". (م)', 'അബൂസലമ(റ): എന്നെ രോഗശയ്യയിലാക്കും വിധമുള്ള സ്വപ്നം ഞാൻ കാണാറുണ്ടായിരുന്നു. അങ്ങനെ ഞാൻ അബൂഖതാദ(റ)യെ കണ്ടുമുട്ടി. അബൂഖതാദ(റ) പറഞ്ഞു: രോഗിയാക്കും വിധമുള്ള സ്വപ്നങ്ങൾ ഞാനും കാണാറുണ്ടായിരുന്നു. ശേഷം റസൂൽ(സ) ഇപ്രകാരം പറയുന്നതായിട്ട് ഞാൻ കേട്ടു. "നല്ല സ്വപ്നങ്ങൾ അല്ലാഹുവിൽ നിന്നുള്ളതാണ്. നിങ്ങളിലൊരാൾ താൻ ഇഷ്ടപ്പെടുന്നത് കണ്ടാൽ താൻ ഇഷ്ടപ്പെടുന്നവരോടല്ലാതെ സംസാരിക്കരുത്. താൻ വെറുക്കുന്നത് കണ്ടാൽ ഇടതു ഭാഗത്തേക്ക് മൂന്ന് പ്രാവശ്യം തുപ്പുകയും അതിന്റെയും പിശാചിന്റെയും തിന്മയിൽ നിന്ന് അല്ലാഹുവിനോട് കാവലിനെ ചോദിക്കുകയും അത് ജനങ്ങളോട് സംസാരിക്കാതിരിക്കുകയും ചെയ്യുക. എന്നാൽ അത് അവന് ബുദ്ധിമുട്ടുണ്ടാക്കുകയില്ല." (മു)', 'أَبِي سَلَمَةَ قَالَ', 'അബൂസലമ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 858, 858, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا رَأَى أَحَدُكُمُ الرُّؤْيَا يُحِبُّهَا، فَإِنَّهَا مِنَ اللهِ، فَلْيَحْمَدِ اللهَ عَلَيْهَا وَلْيُحَدِّثْ بِهَا، وَإِذَا رَأَى غَيْرَ ذَلِكَ مِمَّا يَكْرَهُ، فَإِنَّمَا هِيَ مِنَ الشَّيْطَانِ، فَلْيَسْتَعِذْ مِنْ شَرِّهَا، وَلَا يَذْكُرْهَا لِأَحَدٍ، فَإِنَّهَا لَنْ تَضُرَّهُ". (خ)', 'അബൂസഇൗദുൽ ഖുദ്രി(റ): നബി(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "നിങ്ങളിലൊരുത്തൻ താൻ ഇഷ്ടപ്പെടുന്ന സ്വപ്നം കണ്ടാൽ അത് അല്ലാഹുവിൽ നിന്നാണ്. അതിന്റെ പേരിൽ അവൻ അല്ലാഹുവിനെ സ്തുതിക്കുകയും അത് മറ്റുള്ളവരോട് പറയുകയും വേണം. ഇതല്ലാത്ത താൻ വെറുക്കുന്ന സ്വപ്നം കണ്ടാൽ അത് പിശാചിൽ നിന്നുള്ളതാണ്. അതിന്റെ തിന്മയിൽ നിന്ന് അവൻ കാവൽ ചോദിക്കുകയും അത് ആരോടും പറയാതിരിക്കുകയും വേണം. എന്നാലത് അവന് ബുദ്ധിമുണ്ടാക്കുകയില്ല." (ബു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദുൽ ഖുദ്രി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 858, 858, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ سَمُرَةَ بْنِ جُنْدَبٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى بِنَا الصُّبْحَ أَقْبَلَ عَلَى النَّاسِ بِوَجْهِهِ، وَقَالَ: "هَلْ رَأَى أَحَدٌ مِنْكُمُ اللَّيْلَةَ رُؤْيَا". حَسَنٌ صَحِيحٌ. (ق,ت)', 'സമുറതുബ്നു ജുൻദുബ്(റ): നബി(സ) ഞങ്ങളോടൊന്നിച്ച് സ്വുബ്ഹ് നിസ്കരിച്ച് കഴിഞ്ഞാൽ ജനങ്ങളിലേക്ക് തിരിഞ്ഞിരുന്ന് ഇപ്രകാരം ചോദിക്കും: "നിങ്ങളിലാരെങ്കിലും ഇന്നലെ രാത്രി വല്ല സ്വപ്നവും കണ്ടിട്ടുണ്ടോ?" (ബു,മു,തു)', 'سَمُرَةَ بْنِ جُنْدَبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 858, 858, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي سَلَمَةَ قَالَ: سَمِعْتُ أَبَا قَتَادَةَ رَضِيَ اللهُ عَنْهُ يَقُولُ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الرُّؤْيَا مِنَ اللهِ وَالْحُلْمُ مِنَ الشَّيْطَانِ، فَإِذَا رَأَى أَحَدُكُمْ شَيْئًا يَكْرَهُهُ فَلْيَنْفُثْ عَنْ يَسَارِهِ ثَلَاثَ مَرَّاتٍ، وَلْيَتَعَوَّذْ بِاللهِ مِنْ شَرِّهَا، فَإِنَّهَا لَنْ تَضُرَّهُ". فَقَالَ: إِنْ كُنْتُ لَأَرَى الرُّؤْيَا أَثْقَلَ عَلَيَّ مِنْ جَبَلٍ، فَمَا هُوَ إِلَّا أَنْ سَمِعْتُ بِهَذَا الْحَدِيثِ فَمَا أُبَالِيهَا. (ق,د,ت,جه)', 'അബൂസലമ(റ): അബൂഖതാദ(റ) പറയുന്നത് ഞാൻ കേട്ടു: നബി(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "സ്വപ്നം അല്ലാഹുവിൽ നിന്നും പൊയ്കിനാവ് പിശാചിൽ നിന്നുമാണ്. നിങ്ങളാരെങ്കിലും താൻ വെറുക്കുന്ന വല്ലതും കണ്ടാൽ തന്റെ ഇടത് ഭാഗത്തേക്ക് മൂന്ന് പ്രാവശ്യം തുപ്പുകയും അതിന്റെ തിന്മയിൽ നിന്ന് അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുകയും ചെയ്യുക. എന്നാൽ അത് അവന് ബുദ്ധിമുട്ടുണ്ടാക്കുകയില്ല." അബൂഖതാദ(റ) പറഞ്ഞു: പർവ്വതങ്ങളേക്കാൾ എനിക്ക് ഭാരം തോന്നിക്കുന്ന സ്വപ്നങ്ങൾ ഞാൻ കാണാറുണ്ടായിരുന്നു. ഈ ഹദീസ് ശ്രവിച്ചതിന് ശേഷം ഞാൻ അവയെ പരിഗണിക്കാറില്ലായിരുന്നു. (ബു,മു,ദ,തു,ജ)', 'أَبِي سَلَمَةَ قَالَ', 'അബൂസലമ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 858, 859, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الرُّؤْيَا ثَلَاثٌ: فَبُشْرَى مِنَ اللهِ، وَحَدِيثُ النَّفْسِ، وَتَخْوِيفٌ مِنَ الشَّيْطَانِ. فَإِنْ رَأَى أَحَدُكُمْ رُؤْيَا تُعْجِبُهُ فَلْيَقُصَّ إِنْ شَاءَ، وَإِنْ رَأَى شَيْئًا يَكْرَهُهُ فَلَا يَقُصَّهُ عَلَى أَحَدٍ، وَلْيَقُمْ يُصَلِّي". [في سنده ضعيف] (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നു: "സ്വപ്നം മൂന്ന് വിധമുണ്ട്: അല്ലാഹുവിൽ നിന്നുള്ള സന്തോഷ വാർത്തയായ സ്വപ്നം, സ്വന്തത്തോടുള്ള സംസാരം, പിശാചിൽ നിന്നുള്ള പേടിപ്പെടുത്തുന്ന സ്വപ്നം. അതിനാൽ നിങ്ങളാരെങ്കിലും സന്തോഷിപ്പിക്കുന്ന വല്ല സ്വപ്നവും കണ്ടാൽ അത് മറ്റുള്ളവരെ അറിയിക്കാം. താൻ വെറുക്കുന്ന സ്വപ്നമാണ് കണ്ടതെങ്കിൽ മറ്റാരെയും അറിയിക്കാതെ അവൻ നമസ്കരിച്ച് കൊള്ളട്ടെ." ഇതിന്റെ പരമ്പരയിൽ ഒരു ബലഹീനനുണ്ട്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في سنده ضعيف', null, 859, 859, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ عَوْفِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الرُّؤْيَا ثَلَاثٌ: مِنْهَا أَهَاوِيلُ مِنَ الشَّيْطَانِ لِيُحْزِنَ بِهَا ابْنَ آدَمَ، وَمِنْهَا مَا يَهُمُّ بِهِ الرَّجُلُ فِي يَقْظَتِهِ فَيَرَاهُ فِي مَنَامِهِ، وَمِنْهَا جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنَ النُّبُوَّةِ". قَالَ: قُلْتُ لَهُ: أَنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ: أَنَا سَمِعْتُهُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، أَنَا سَمِعْتُهُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (جه)', 'ഔഫുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "സ്വപ്നം മൂന്ന് വിധമുണ്ട്. മനുഷ്യനെ ദുഃഖിപ്പിക്കാൻ വേണ്ടിയുള്ള പിശാചിൽ നിന്നുള്ള പേടിപ്പെടുത്തലുകൾ അതിൽ പെട്ടതാണ്, ഉണർച്ചയിൽ മുഖ്യമായി കാണുന്ന കാര്യങ്ങൾ സ്വപ്നത്തിൽ ദർശിക്കൽ അതിൽ പെട്ടതാണ്, നുബുവ്വതിന്റെ നാൽപ്പത്തിയാറിൽ ഒരു അംശമായ സ്വപ്നവും അതിൽ പെട്ടതാണ്." താങ്കൾ ഇത് റസൂലിൽ നിന്ന് കേട്ടതാണോ എന്ന് നിവേദകൻ ഔഫുബ്നു മാലിക്(റ)വിനോട് ചോദിച്ചു. ഔഫ്(റ) പറഞ്ഞു: അതെ, ഞാൻ അത് റസൂൽ(സ)യിനിന്ന് ശ്രവിച്ചതാണ്, ഞാൻ അത് റസൂൽ(സ)യിനിന്ന് ശ്രവിച്ചതാണ്. (ജ)', 'عَوْفِ بْنِ مَالِكٍ', 'ഔഫുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 859, 859, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الرُّؤْيَا مِنَ اللهِ، وَالْحُلْمُ مِنَ الشَّيْطَانِ. فَإِذَا رَأَى أَحَدُكُمْ شَيْئًا يَكْرَهُهُ فَلْيَبْصُقْ عَنْ يَسَارِهِ ثَلَاثًا، وَلْيَسْتَعِذْ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ ثَلَاثًا، وَلْيَتَحَوَّلْ عَنْ جَنْبِهِ الَّذِي كَانَ عَلَيْهِ". (ق,د,ت,جه)', 'അബൂഖതാദ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "സ്വപ്നം അല്ലാഹുവിൽ നിന്നുള്ളതാണ്. പൊയ്ക്കിനാവ് പിശാചിൽ നിന്നുള്ളതാണ്. അതിനാൽ നിങ്ങളിൽ ആരെങ്കിലും താൻ വെറുക്കുന്ന വല്ലതും കണ്ടാൽ തന്റെ ഇടതു ഭാഗത്തേക്ക് മൂന്ന് പ്രാവശ്യം തുപ്പുകയും പിശാചിൽ നിന്ന് അല്ലാഹുവിനോട് കാവലിനെ ചോദിക്കുകയും താൻ നിലകൊള്ളുന്ന ഭാഗത്തു നിന്ന് മാറിനിൽക്കുകയും ചെയ്യുക." (ബു,മു,ദ,തു,ജ)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 859, 859, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا رَأَى أَحَدُكُمْ رُؤْيَا يَكْرَهُهَا فَلْيَتَحَوَّلْ، وَلْيَتْفُلْ عَنْ يَسَارِهِ ثَلَاثًا، وَلْيَسْأَلِ اللهَ مِنْ خَيْرِهَا، وَلْيَتَعَوَّذْ مِنْ شَرِّهَا". [في سنده ضعيف] (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും താൻ വെറുക്കുന്ന സ്വപ്നം കണ്ടാൽ അവൻ സ്ഥലം മാറുകയും ഇടതു ഭാഗത്തേക്ക് മൂന്ന് പ്രാവശ്യം തുപ്പുകയും അതിലെ നന്മയെ അല്ലാഹുവിനോട് ചോദിക്കുകയും അതിലെ തിന്മയെ തൊട്ട് അല്ലാഹുവിനോട് കാവലിനെ ചോദിക്കുകയും ചെയ്യട്ടെ." ഇതിന്റെ പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في سنده ضعيف', null, 859, 860, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنْتُ غُلَامًا شَابًّا عَزَبًا، فِي عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَكُنْتُ أَبِيتُ فِي الْمَسْجِدِ، فَكَانَ مَنْ رَأَى مِنَّا رُؤْيَا يَقُصُّهَا عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: اللَّهُمَّ إِنْ كَانَ لِي عِنْدَكَ خَيْرٌ فَأَرِنِي رُؤْيًا يُعَبِّرُهَا لِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَنِمْتُ، فَرَأَيْتُ مَلَكَيْنِ أَتَيَانِي فَانْطَلَقَا بِي، فَلَقِيَهُمَا مَلَكٌ آخَرُ، فَقَالَ: لَمْ تُرَعْ. فَانْطَلَقَا بِي إِلَى النَّارِ، فَإِذَا هِيَ مَطْوِيَّةٌ كَطَيِّ الْبِئْرِ، وَإِذَا فِيهَا نَاسٌ قَدْ عَرَفْتُ بَعْضَهُمْ، فَأَخَذُوا بِي ذَاتَ الْيَمِينِ. فَلَمَّا أَصْبَحْتُ ذَكَرْتُ ذَلِكَ لِحَفْصَةَ رَضِيَ اللهُ عَنْهَا، فَزَعَمَتْ حَفْصَةُ أَنَّهَا قَصَّتْهَا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "إِنَّ عَبْدَ اللهِ رَجُلٌ صَالِحٌ، لَوْ كَانَ يُكْثِرُ الصَّلَاةَ مِنَ اللَّيْلِ". قَالَ: فَكَانَ عَبْدُ اللهِ يُكْثِرُ الصَّلَاةَ مِنَ اللَّيْلِ. (ق,جه)', 'ഇബ്നുഉമർ(റ): ഞാൻ റസൂൽ(സ)യുടെ കാലത്ത് അവിവാഹിതനായ യുവാവായിരുന്നു. ഞാൻ പള്ളിയിൽ അന്തിയുറങ്ങാറുണ്ടായിരുന്നു. ഞങ്ങളാരെങ്കിലും വല്ല സ്വപ്നവും കണ്ടാൽ അത് റസൂൽ(സ)യോട് വിവരിച്ചുകൊടുക്കുന്നതായിരുന്നു ഞങ്ങളുടെ പതിവ്. ഞാൻ ഇപ്രകാരം പ്രാർത്ഥിച്ചു: അല്ലാഹുവേ, എനിക്ക് നിന്റെ പക്കൽ വല്ല നന്മയുമുണ്ടെങ്കിൽ നബി(സ) വ്യാഖ്യാനിച്ചുതരുംവിധം വല്ല സ്വപ്നവും എനിക്ക് കാണിക്കണേ. അങ്ങനെ ഞാൻ ഉറങ്ങി. ഉറക്കത്തിൽ രണ്ട് മലക്കുകൾ വന്ന് എന്നെ കൊണ്ടുപോകുന്നതായി ഞാൻ കണ്ടു. ആ രണ്ടു മലക്കുകളെ മറ്റൊരു മലക്ക് കണ്ടുമുട്ടി. ആ മലക്ക് പറഞ്ഞു: നീ പേടിപ്പിക്കപ്പെടുകയില്ല. അവരെന്നെ നരകത്തിലേക്ക് കൊണ്ടുപോയി. നരകം കിണറിന്റെ ചുറ്റുമതിൽ പോലെ കല്ലുകൊണ്ട് പടുക്കപ്പെട്ടതാണ്. അതിൽ എനിക്ക് പരിചയമുള്ള ചില മനുഷ്യരുണ്ട്. അവരെന്റെ വലതു ഭാഗത്ത് പിടിച്ചു. നേരം പുലർന്നപ്പോൾ വിവരം ഞാൻ ഹഫ്സ(റ)യോട് പറഞ്ഞുകൊടുത്തു. താൻ ആ സ്വപ്നം റസൂൽ(സ)യോട് പറഞ്ഞുകൊടുത്തുവെന്നും അപ്പോൾ, "അബ്ദുല്ല നല്ല വ്യക്തിയാണ്, അവൻ രാത്രിയിലെ നമസ്കാരത്തെ വർധിപ്പിച്ചിരുന്നെങ്കിൽ നല്ലത്" എന്ന് നബി(സ) പറഞ്ഞുവെന്നും ഹഫ്സ(റ) പറഞ്ഞു. നിവേദകൻ പറഞ്ഞു: ഇതിനുശേഷം അബ്ദുല്ല(റ) രാത്രിയിലെ നമസ്കാരം അധികരിപ്പിക്കാറുണ്ടായിരുന്നു. (ബു,മു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 860, 860, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ خَرَشَةَ بْنِ الْحُرِّ قَالَ: قَدِمْتُ الْمَدِينَةَ فَجَلَسْتُ إِلَى شِيَخَةٍ فِي مَسْجِدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ شَيْخٌ يَتَوَكَّأُ عَلَى عَصًا لَهُ، فَقَالَ الْقَوْمُ: مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى رَجُلٍ مِنْ أَهْلِ الْجَنَّةِ فَلْيَنْظُرْ إِلَى هَذَا. فَقَامَ خَلْفَ سَارِيَةٍ، فَصَلَّى رَكْعَتَيْنِ. فَقُمْتُ إِلَيْهِ، فَقُلْتُ لَهُ: قَالَ بَعْضُ الْقَوْمِ كَذَا وَكَذَا. قَالَ: الْحَمْدُ لِلَّهِ، الْجَنَّةُ لِلَّهِ يُدْخِلُهَا مَنْ يَشَاءُ، وَإِنِّي رَأَيْتُ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رُؤْيَا: رَأَيْتُ كَأَنَّ رَجُلًا أَتَانِي فَقَالَ لِي: انْطَلِقْ. فَذَهَبْتُ مَعَهُ، فَسَلَكَ بِي فِي نَهْجٍ عَظِيمٍ، فَعُرِضَتْ عَلَيَّ طَرِيقٌ عَلَى يَسَارِي، فَأَرَدْتُ أَنْ أَسْلُكَهَا، فَقَالَ: إِنَّكَ لَسْتَ مِنْ أَهْلِهَا. ثُمَّ عُرِضَتْ عَلَيَّ طَرِيقٌ عَنْ يَمِينِي، فَسَلَكْتُهَا، حَتَّى إِذَا انْتَهَيْتُ إِلَى جَبَلٍ زَلَقٍ فَأَخَذَ بِيَدِي فَزَجَلَ بِي، فَإِذَا أَنَا عَلَى ذُرْوَتِهِ، فَلَمْ أَتَقَارَّ وَلَمْ أَتَمَاسَكْ، وَإِذَا عَمُودٌ مِنْ حَدِيدٍ، فِي ذُرْوَتِهِ حَلْقَةٌ مِنْ ذَهَبٍ، فَأَخَذَ بِيَدِي فَزَجَلَ بِي حَتَّى أَخَذْتُ بِالْعُرْوَةِ، فَقَالَ: اسْتَمْسَكْتَ؟ قُلْتُ: نَعَمْ. فَضَرَبَ الْعَمُودَ بِرِجْلِهِ، فَاسْتَمْسَكْتُ بِالْعُرْوَةِ. فَقَالَ: قَصَصْتُهَا عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رَأَيْتَ خَيْرًا، أَمَّا الْمَنْهَجُ الْعَظِيمُ فَالْمَحْشَرُ، وَأَمَّا الطَّرِيقُ الَّتِي عُرِضَتْ عَنْ يَسَارِكَ فَطَرِيقُ أَهْلِ النَّارِ، وَلَسْتَ مِنْ أَهْلِهَا. وَأَمَّا الطَّرِيقُ الَّتِي عُرِضَتْ عَنْ يَمِينِكَ فَطَرِيقُ أَهْلِ الْجَنَّةِ، وَأَمَّا الْجَبَلُ الزَّلَقُ فَمَنْزِلُ الشُّهَدَاءِ، وَأَمَّا الْعُرْوَةُ الَّتِي اسْتَمْسَكْتَ بِهَا فَعُرْوَةُ الْإِسْلَامِ، فَاسْتَمْسِكْ بِهَا حَتَّى تَمُوتَ". فَأَنَا أَرْجُو أَنْ أَكُونَ مِنْ أَهْلِ الْجَنَّةِ. فَإِذَا هُوَ عَبْدُ اللهِ بْنُ سَلَامٍ. (م,جه)', 'ഖറശതുബ്നുൽ ഹുർറ്(റ): ഞാൻ മദീനയിൽ വന്നു. നബി(സ)യുടെ പള്ളിയിൽ കയറി ചില വൃദ്ധരുടെ സമീപത്തിരുന്നു. അപ്പോൾ ഒരു വൃദ്ധൻ വടികുത്തി അങ്ങോട്ട് വന്നു. അപ്പോൾ ചിലർ പറഞ്ഞു: ആർക്കെങ്കിലും ഒരു സ്വർഗ്ഗവാസിയിലേക്ക് നോക്കാൻ ആഗ്രഹമുണ്ടെങ്കിൽ ഇദ്ദേഹത്തെ നോക്കിക്കൊള്ളൂ. അപ്പോൾ അദ്ദേഹം ഒരു തൂണിന്റെ പിറകിലേക്ക് മാറിനിന്ന് രണ്ടു റക്അത് നിസ്കരിച്ചു. അപ്പോൾ ഞാൻ അദ്ദേഹത്തിന്റെ അടുത്ത് ചെന്ന് അദ്ദേഹത്തോട് പറഞ്ഞു: ജനങ്ങൾ താങ്കളെക്കുറിച്ച് ഇപ്രകാരമൊക്കെ പറഞ്ഞു. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന് സ്തുതി. സ്വർഗ്ഗം അല്ലാഹുവിന്റേതാണ്. അവൻ ഉദ്ധേശിച്ചവരെ അതിൽ പ്രവേശിപ്പിക്കും. നബി(സ)യുടെ കാലത്ത് ഞാനൊരു സ്വപ്നം കണ്ടു. ഒരാൾ എന്റടുത്ത് വന്നതായി ഞാൻ കണ്ടു. അയാൾ പറഞ്ഞു: വരൂ. ഞാൻ അദ്ദേഹത്തിന്റെ കൂടെ പോയി. ഞാനുമായി അദ്ദേഹം വലിയൊരു പാതയിൽ പ്രവേശിച്ചു. അന്നേരം എന്റെ ഇടതുഭാഗത്ത് മറ്റൊരു വഴികൂടി ഞാൻ കാണുകയും അതിൽ പ്രവേശിക്കണമെന്ന് ആഗ്രഹിക്കുകയും ചെയ്തു. അദ്ദേഹം പറഞ്ഞു: താങ്കൾ ആ വഴിയുടെ ആളല്ല. ശേഷം എന്റെ വലതുഭാഗത്ത് ഒരു വഴി കാണുകയും ഞാൻ അതിൽ പ്രവേശിക്കുകയും ചെയ്തു. അങ്ങനെ ഞാൻ വഴുതുന്ന ഒരു മലയുടെ മുകളിൽ കയറുകയും അദ്ദേഹം എന്റെ കൈ പിടിച്ച് എന്നെ എറിയുകയും ചെയ്തു. അങ്ങനെ ഞാൻ ആ മലയുടെ അഗ്രഭാഗത്തെത്തി. പക്ഷേ, എനിക്കവിടെ ഉറച്ചുനിൽക്കാൻ സാധിച്ചില്ല. അന്നേരം ഒരു ഇരുമ്പിൻ തൂണ് കണ്ടു. അതിന്റെ അറ്റത്ത് ഒരു സ്വർണ്ണക്കണ്ണിയുണ്ട്. അദ്ദേഹം എന്റെ കൈ പിടിച്ച് എറിയുകയും ഞാൻ ആ പിടുത്തത്തിൽ പിടിക്കുകയും ചെയ്തു. നിങ്ങൾ മുറുക്കിപ്പിടിച്ചുവോ എന്ന് അദ്ദേഹം ചോദിച്ചു. ഞാൻ പറഞ്ഞു: അതെ. അപ്പോൾ അദ്ദേഹം തന്റെ കാലുകൊണ്ട് ആ തൂണിലടിക്കുകയും ഞാൻ ആ പിടുത്തത്തിൽ മുറുകെപ്പിടിക്കുകയും ചെയ്തു. ആ വൃദ്ധൻ പറഞ്ഞു: ഞാൻ ആ സ്വപ്നം നബി(സ)ക്ക് വിവരിച്ചു കൊടുത്തു. നബി(സ) പറഞ്ഞു: "നീ കണ്ടത് നന്മയാണ്, നീ കണ്ട വലിയ പാത പരലോകമാണ്. നിന്റെ ഇടതുഭാഗത്ത് പ്രത്യക്ഷപ്പെട്ട പാത നരകവാസികളുടെ പാതയാണ്. നീ അതിന്റെ ആളല്ല. എന്നാൽ നിന്റെ വലതുഭാഗത്ത് പ്രത്യക്ഷപ്പെട്ട പാത സ്വർഗ്ഗക്കാരുടെ പാതയാണ്. ആ വഴുതുന്ന മല രക്തസാക്ഷികളുടെ സ്ഥാനമാണ്. നീ മുറുകെപ്പിടിച്ച പിടുത്തം ഇസ്ലാമിന്റെ പിടുത്തമാണ്. അതുകൊണ്ട് മരിക്കുംവരെ നീയത് മുറുകെപ്പിടിക്കുക." ഞാൻ സ്വർഗ്ഗക്കാരിൽ പെടണമെന്ന് ഞാൻ ആഗ്രഹിക്കുന്നു. ആ വൃദ്ധൻ അബ്ദുല്ലാഹിബ്നു സലാം(റ) ആയിരുന്നു. (മു,ജ)', 'خَرَشَةَ بْنِ الْحُرِّ قَالَ', 'ഖറശതുബ്നുൽ ഹുർറ്(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 860, 861, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ بْنِ عُتْبَةَ: أَنَّ ابْنَ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا كَانَ يُحَدِّثُ: أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي أَرَى اللَّيْلَةَ فِي الْمَنَامِ ظُلَّةً تَنْطُفُ السَّمْنَ وَالْعَسَلَ، فَأَرَى النَّاسَ يَتَكَفَّفُونَ مِنْهَا بِأَيْدِيهِمْ، فَالْمُسْتَكْثِرُ وَالْمُسْتَقِلُّ، وَأَرَى سَبَبًا وَاصِلًا مِنَ السَّمَاءِ إِلَى الْأَرْضِ، فَأَرَاكَ أَخَذْتَ بِهِ فَعَلَوْتَ، ثُمَّ أَخَذَ بِهِ رَجُلٌ مِنْ بَعْدِكَ فَعَلَا، ثُمَّ أَخَذَ بِهِ رَجُلٌ آخَرُ فَعَلَا، ثُمَّ أَخَذَ بِهِ رَجُلٌ آخَرُ فَانْقَطَعَ بِهِ، ثُمَّ وُصِلَ لَهُ فَعَلَا. قَالَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ: يَا رَسُولَ اللهِ، بِأَبِي أَنْتَ، وَاللهِ لَتَدَعَنِّي فَلَأَعْبُرَنَّهَا. قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَعْبُرْهَا". فَقَالَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ: أَمَّا الظُّلَّةُ فَظُلَّةُ الْإِسْلَامِ، وَأَمَّا الَّذِي يَنْطُفُ مِنَ السَّمْنِ وَالْعَسَلِ فَالْقُرْآنُ حَلَاوَتُهُ وَلِينُهُ، وَأَمَّا مَا يَتَكَفَّفُ النَّاسُ مِنْ ذَلِكَ فَالْمُسْتَكْثِرُ مِنَ الْقُرْآنِ وَالْمُسْتَقِلُّ [مِنْهُ]. وَأَمَّا السَّبَبُ الْوَاصِلُ مِنَ السَّمَاءِ إِلَى الْأَرْضِ فَالْحَقُّ الَّذِي أَنْتَ عَلَيْهِ، تَأْخُذُ بِهِ فَيُعْلِيكَ اللهُ [بِهِ]، ثُمَّ يَأْخُذُ بِهِ رَجُلٌ مِنْ بَعْدِكَ فَيَعْلُو بِهِ، ثُمَّ يَأْخُذُ بِهِ رَجُلٌ آخَرُ فَيَعْلُو بِهِ، ثُمَّ يَأْخُذُ بِهِ رَجُلٌ آخَرُ فَيَنْقَطِعُ بِهِ، ثُمَّ يُوصَلُ لَهُ فَيَعْلُو بِهِ، فَأَخْبِرْنِي يَا رَسُولَ اللهِ، بِأَبِي أَنْتَ [وَ أُمِّي]، أَصَبْتُ أَمْ أَخْطَأْتُ؟ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ "أَصَبْتَ بَعْضًا وَأَخْطَأْتَ بَعْضًا". قَالَ: فَوَاللهِ يَا رَسُولَ اللهِ، لَتُحَدِّثَنِّي مَا الَّذِي أَخْطَأْتُ؟ قَالَ: "لَا تُقْسِمْ". (ق,د,ت,ن,جه)', 'ഉബൈദുല്ലാഹിബ്നു അബ്ദുല്ലാഹിബ്നു ഉത്ബ(റ): ഇബ്നു അബ്ബാസ്(റ) പറയാറുണ്ടായിരുന്നു: ഒരു മനുഷ്യൻ നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, തേനും നെയ്യും വർഷിച്ചുകൊണ്ടിരിക്കുന്ന ഒരു മേഘം ഞാൻ ഇന്നലെ രാത്രി സ്വപ്നത്തിൽ ദർശിച്ചു. ജനങ്ങളെല്ലാം അതിൽ നിന്ന് എടുത്ത് കൊണ്ടിരിക്കുന്നു. അവരിൽ ധാരാളം ലഭിച്ചവരും അൽപം മാത്രം ലഭിച്ചവരുമുണ്ട്. ആകാശത്ത് നിന്ന് ഭൂമിയിലേക്ക് നീണ്ടുകിടക്കുന്ന ഒരു കയറും ഞാൻ കണ്ടു. നബിയേ, അങ്ങ് ആ കയറ് പിടിച്ച് ഉയരുന്നതായും ഞാൻ കണ്ടു. ശേഷം മറ്റൊരാൾ അത് പിടിച്ചു. അദ്ദേഹവും ഉയർന്നു. മറ്റൊരാൾ കൂടി അത് പിടിച്ചു, അദ്ദേഹവും ഉയർന്നു. പിന്നെ മറ്റൊരാൾ അതിൽ പിടിച്ചപ്പോൾ ആ കയററ് അദ്ദേഹം വീണു. ശേഷം അയാൾക്ക് വേണ്ടി ആ കയർ കെട്ടപ്പെടുകയും അദ്ദേഹം ഉയരുകയും ചെയ്തു. അബൂബക്കർ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ പിതാവ് അങ്ങേക്ക് ദണ്ഡമാണ്, അല്ലാഹു തന്നെ സത്യം! എനിക്ക് വിട്ടു തന്നാൽ ആ സ്വപ്നം ഞാൻ വ്യാഖ്യാനിക്കുക തന്നെ ചെയ്യും. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളതു വ്യാഖ്യാനിക്കുക." അപ്പോൾ അബൂബക്കർ(റ) പറഞ്ഞു: ആ മേഘം ഇസ്ലാമിന്റെ മേഘമാണ്. അതിൽ നിന്ന് വർഷിക്കുന്ന തേനും നെയ്യും ഖുർആനാണ്; അഥവാ ഖുർആന്റെ ലാളിത്യവും മാധുര്യവും. ജനങ്ങൾ അതിൽ നിന്ന് വാരിക്കൊണ്ടിരിക്കുന്നത് ഖുർആനിൽ നിന്ന് കൂടുതൽ ലഭിച്ചവരും അൽപം ലഭിച്ചവരുമാണ്. ആകാശത്ത് നിന്ന് ഭൂമിയിലേക്ക് നീണ്ടുകിടക്കുന്ന കയർ, നബിയേ അങ്ങ് നിലകൊള്ളുന്നു ഹഖ്(സത്യം) ആണ്. അങ്ങ് അത് പിടിക്കുകയും അതുകൊണ്ട് അല്ലാഹു അങ്ങയെ ഉയർത്തുകയും ചെയ്യുന്നു. അങ്ങേക്കു ശേഷം മറ്റൊരാൾ അത് പിടിക്കുകയും അദ്ദേഹം ഉയരുകയും ചെയ്യുന്നു. ശേഷം മറ്റൊരാൾ അത് പിടിക്കുകയും ഉയരുകയും ചെയ്യുന്നു. ശേഷം മറ്റൊരാൾ അത് പിടിക്കുമ്പോൾ അത് പൊട്ടി വീഴുകയും പിന്നെ അത് ബന്ധിച്ച് കൊടുക്കുമ്പോൾ അദ്ദേഹം ഉയരുകയും ചെയ്യുന്നു. റസൂലേ, എന്റെ ഉമ്മയും ഉപ്പയും അങ്ങേക്ക് ദണ്ണമാണ്. ഞാൻ പറഞ്ഞത് തെറ്റോ ശരിയോ എന്ന് അങ്ങ് പറഞ്ഞുതരിക. റസൂൽ(സ) പറഞ്ഞു: "നീ പറഞ്ഞതിൽ ചിലത് തെറ്റും ചിലത് ശരിയുമാണ്." അബൂബക്കർ(റ) പറഞ്ഞു: റസൂലേ, അല്ലാഹു തന്നെ സത്യം! എനിക്കു പറ്റിയ പിഴവു പറഞ്ഞു തരിക. റസൂൽ പറഞ്ഞു: "നീ സത്യം ചെയ്യരുത്." (ബു,മു,ദ,തു,ന,ജ)', 'عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ بْنِ عُتْبَةَ', 'ഉബൈദുല്ലാഹിബ്നു അബ്ദുല്ലാഹിബ്നു ഉത്ബ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], 'وَ أُمِّي', null, 861, 862, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَبِي رَزِينٍ الْعُقَيْلِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "رُؤْيَا الْمُؤْمِنِ جُزْءٌ مِنْ أَرْبَعِينَ جُزْءاً مِنَ النُّبُوَّةِ، وَهِيَ عَلَى رِجْلِ طَائِرٍ مَا لَمْ يَتَحَدَّثْ بِهَا، فَإِذَا تَحَدَّثَ بِهَا سَقَطَتْ، وَلَا يُحَدِّثُ بِهَا إِلَّا لَبِيبًا أَوْ حَبِيبًا". وَفِي رِوَايَةٍ: رُؤْيَا الْمُسْلِمِ جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنَ النُّبُوَّةِ، وَهِيَ عَلَى رِجْلِ طَائِرٍ مَا لَمْ يُحَدِّثْ بِهَا، فَإِذَا حُدِّثَ بِهَا وَقَعَتْ". حَسَنٌ صَحِيحٌ. (د,ت)', 'അബൂറസീനുൽ ഉഖൈലി(റ): നബി(സ) പറഞ്ഞു: "വിശ്വാസിയുടെ സ്വപ്നം നുബുവ്വത്തിന്റെ നാൽപതിൽ ഒരു അംശമാണ്. സ്വപ്നവിവരം മറ്റുള്ളവരോട് പറയുംവരെ അത് പക്ഷിയുടെ കാലിന്മേലെന്ന പോലെയാണ്. അത് മറ്റുള്ളവരോട് പറഞ്ഞാൽ അത് വീഴും (സംഭവിക്കും). അതുകൊണ്ട് ബുദ്ധിമാനോടോ സ്നേഹിതനോടോ അല്ലാതെ സ്വപ്നം വിവരിക്കരുത്. മറ്റൊരു നിവേദനം: മുസ്ലിമിന്റെ സ്വപ്നം നുബുവ്വത്തിന്റെ നാൽപത്തിയാറിൽ ഒരു അംശമാണ്. അത് മറ്റുള്ളവരോട് അറിയിക്കാത്ത കാലത്തോളം പക്ഷിയുടെ കാലിന്മേലെന്ന പോലെയാണ്. മറ്റുള്ളവരെ അറിയിച്ചാൽ അത് സംഭവിക്കും." (ദ,തു)', 'أَبِي رَزِينٍ الْعُقَيْلِيِّ', 'അബൂറസീനുൽ ഉഖൈലി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 862, 862, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=15 and h.hadith_no=37), 1, 'وَفِي رِوَايَةٍ: رُؤْيَا الْمُسْلِمِ جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنَ النُّبُوَّةِ، وَهِيَ عَلَى رِجْلِ طَائِرٍ مَا لَمْ يُحَدِّثْ بِهَا، فَإِذَا حُدِّثَ بِهَا وَقَعَتْ". حَسَنٌ صَحِيحٌ. (د,ت)', 'മറ്റൊരു നിവേദനം: മുസ്ലിമിന്റെ സ്വപ്നം നുബുവ്വത്തിന്റെ നാൽപത്തിയാറിൽ ഒരു അംശമാണ്. അത് മറ്റുള്ളവരോട് അറിയിക്കാത്ത കാലത്തോളം പക്ഷിയുടെ കാലിന്മേലെന്ന പോലെയാണ്. മറ്റുള്ളവരെ അറിയിച്ചാൽ അത് സംഭവിക്കും." (ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "رَأَيْتُ فِي يَدِي سِوَارَيْنِ مِنْ ذَهَبٍ، فَنَفَخْتُهُمَا فَأَوَّلْتُهُمَا هَذَيْنِ الْكَذَّابَيْنِ: مُسَيْلِمَةَ وَالْعَنْسِيَّ". (جه)', 'അബൂഹുറൈറ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ഞാൻ എന്റെ കയ്യിൽ രണ്ട് സ്വർണ്ണവളകൾ കാണുകയും അവ ഊതിക്കളയുകയും ചെയ്തു. മുസൈലിമ, അൻസി എന്ന് പേരുള്ള ഈ രണ്ട് കള്ളവാദികളായിട്ടാണ് ഞാനവയെ വ്യാഖ്യാനിച്ചത്." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 862, 862, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ أُمِّ الْفَضْلِ رَضِيَ اللهُ عَنْهُمَا قَالَتْ: يَا رَسُولَ اللهِ، رَأَيْتُ كَأَنَّ فِي بَيْتِي عُضْوًا مِنْ أَعْضَائِكَ. قَالَ: "خَيْرًا رَأَيْتِ. تَلِدُ فَاطِمَةُ غُلَامًا فَتُرْضِعِيهِ". فَوَلَدَتْ حُسَيْنًا أَوْ حَسَنًا، فَأَرْضَعَتْهُ بِلَبَنِ قُثَمٍ. قَالَتْ: فَجِئْتُ بِهِ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَوَضَعْتُهُ فِي حَجْرِهِ فَبَالَ، فَضَرَبْتُ كَتِفَهُ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَوْجَعْتِ ابْنِي، رَحِمَكِ اللهُ". (جه)', 'ഉമ്മുഫള്ൽ(റ): മഹതി പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ വീട്ടിൽ അങ്ങയുടെ ഒരു അവയവം ഉള്ളതുപോലെ ഞാൻ സ്വപ്നം കണ്ടു. നബി(സ) പറഞ്ഞു: "നീ കണ്ടത് നന്മയാണ്. ഫാതിമ ഒരാൺകുഞ്ഞിനെ പ്രസവിക്കുകയും നീ അവനെ പാലൂട്ടുകയും ചെയ്യും." അങ്ങനെ ഫാതിമ(റ) ഹുസൈനെയോ ഹസനെയോ പ്രസവിച്ചു. അങ്ങനെ ഖുസമിന്റെ പാലുകൊണ്ട് മഹതി അവരെ പോറ്റി. മഹതി പറയുന്നു: പിന്നെ ഞാൻ കുട്ടിയെ നബി(സ)യുടെ അടുത്തേക്ക് കൊണ്ടുപോയി. കുട്ടിയെ നബി(സ)യുടെ മടിയിൽ വെച്ചപ്പോൾ കുട്ടി മൂത്രമൊഴിച്ചു. അപ്പോൾ ഞാൻ കുട്ടിയുടെ തോളത്തടിച്ചു. ഉടനെ നബി(സ) പറഞ്ഞു: "നീ എന്റെ മകനെയാണ് വേദനിപ്പിച്ചത്, അല്ലാഹു നിനക്ക് കരുണ ചെയ്യട്ടെ." (ജ)', 'أُمِّ الْفَضْلِ', 'ഉമ്മുഫള്ൽ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 863, 863, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنْ رُؤْيَا النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رَأَيْتُ امْرَأَةً سَوْدَاءَ ثَائِرَةَ الرَّأْسِ، خَرَجَتْ مِنَ الْمَدِينَةِ حَتَّى قَامَتْ بِالْمَهْيَعَةِ، وَهِيَ الْجُحْفَةُ. فَأَوَّلْتُهَا وَبَاءً بِالْمَدِينَةِ، فَنُقِلَ إِلَى الْجُحْفَةِ". (خ,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) നബി(സ)യുടെ സ്വപ്നത്തെക്കുറിച്ച്: നബി(സ) പറഞ്ഞു: "തലമുടി ചിതറിയ കറുത്ത ഒരു സ്ത്രീയെ ഞാൻ സ്വപ്നത്തിൽ കണ്ടു. അവൾ മദീനയിൽനിന്ന് പോയി മഹ്യഅഃ എന്ന സ്ഥലത്ത് നിന്നു. മഹ്യഅഃ എന്നാൽ ജുഹ്ഫ എന്ന നാടാണ്. മദീനയിലെ പ്ലാഗ് ജുഹ്ഫയിലേക്ക് നീക്കപ്പെട്ടു എന്ന് ഞാൻ ആ സ്വപ്നത്തെ വ്യാഖ്യാനിച്ചു." (ബു,തു,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ','ت','جه']::text[], array['ബു','തു','ജ']::text[], null, null, 863, 863, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اعْتَبِرُوهَا بِأَسْمَائِهَا، وَكَنُّوهَا بِكُنَاهَا، وَالرُّؤْيَا لِأَوَّلِ عَابِرٍ". [ز: في سنده ضعيف] (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "സ്വപ്നങ്ങളെ അതിലെ പേരുകൾക്കനുസരിച്ച് നിങ്ങൾ വ്യാഖ്യാനിക്കുക. അതിലെ സൂചനകൾക്കനുസരിച്ച് നിങ്ങളതിന് സൂചനകൾ നൽകുക. സ്വപ്നം അതിനെ ആദ്യം വ്യാഖ്യാനിക്കുന്നവനനുസരിച്ചാണ് (സംഭവിക്കുക)." ഇതിന്റെ പരമ്പരയിൽ ഒരു ബലഹീനനുണ്ട്. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 863, 863, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ طَلْحَةَ بْنِ عُبَيْدِ اللهِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلَيْنِ مِنْ بَلِيٍّ قَدِمَا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ إِسْلَامُهُمَا جَمِيعًا، فَكَانَ أَحَدُهُمَا أَشَدَّ اجْتِهَادًا مِنَ الْآخَرِ، فَغَزَا الْمُجْتَهِدُ مِنْهُمَا فَاسْتُشْهِدَ، ثُمَّ مَكَثَ الْآخَرُ بَعْدَهُ سَنَةً، ثُمَّ تُوُفِّيَ. قَالَ طَلْحَةُ: فَرَأَيْتُ فِي الْمَنَامِ: بَيْنَا أَنَا عِنْدَ بَابِ الْجَنَّةِ إِذَا أَنَا بِهِمَا، فَخَرَجَ خَارِجٌ مِنَ الْجَنَّةِ فَأَذِنَ لِلَّذِي تُوُفِّيَ الْآخِرَ مِنْهُمَا، ثُمَّ خَرَجَ فَأَذِنَ لِلَّذِي اسْتُشْهِدَ، ثُمَّ رَجَعَ إِلَيَّ فَقَالَ: ارْجِعْ، فَإِنَّكَ لَمْ يَأْنِ لَكَ بَعْدُ. فَأَصْبَحَ طَلْحَةُ يُحَدِّثُ بِهِ النَّاسَ، فَعَجِبُوا لِذَلِكَ فَبَلَغَ ذَلِكَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَحَدَّثُوهُ الْحَدِيثَ، فَقَالَ: "مِنْ أَيِّ ذَلِكَ تَعْجَبُونَ". فَقَالُوا: يَا رَسُولَ اللهِ، هَذَا كَانَ أَشَدَّ الرَّجُلَيْنِ اجْتِهَادًا، ثُمَّ اسْتُشْهِدَ، وَدَخَلَ هَذَا الْآخِرُ الْجَنَّةَ قَبْلَهُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَلَيْسَ قَدْ مَكَثَ هَذَا بَعْدَهُ سَنَةً". قَالُوا: بَلَى. قَالَ: "وَأَدْرَكَ رَمَضَانَ فَصَامَ، وَصَلَّى كَذَا وَكَذَا مِنْ سَجْدَةٍ فِي السَّنَةِ". قَالُوا: بَلَى. قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَمَا بَيْنَهُمَا أَبْعَدُ مِمَّا بَيْنَ السَّمَاءِ وَالْأَرْضِ". (جه)', 'ത്വൽഹതുബ്നു ഉബൈദില്ല(റ): ബലിയ്യ് ഗോത്രക്കാരായ രണ്ടുപേർ റസൂൽ(സ)യുടെ അടുത്ത് വന്നു. ഇരുവരും മുസ്ലിമായത് ഒപ്പമായിരുന്നു. അവരിലൊരുവൻ മറ്റവനേക്കാൾ പരിശ്രമിക്കുന്നയാളായിരുന്നു. അദ്ദേഹം യുദ്ധം ചെയ്യുകയും രക്തസാക്ഷിയാവുകയും ചെയ്തു. മറ്റെയാൾ ഒരു വർഷം കൂടി ജീവിക്കുകയും ശേഷം വഫാത്താകുകയും ചെയ്തു. ത്വൽഹ(റ) പറഞ്ഞു: സ്വർഗ്ഗത്തിന്റെ വാതിലിനടുത്ത് ആ രണ്ടുപേർക്കൊപ്പം ഞാൻ നിൽക്കുന്നതായി ഞാൻ സ്വപ്നം കണ്ടു. അന്നേരം സ്വർഗ്ഗത്തിൽ നിന്നൊരാൾ വന്ന് അവരിൽ നിന്ന് വഫാതായിപ്പോയ രണ്ടാമന് സ്വർഗ്ഗപ്രവേശനത്തിന് അനുവാദം നൽകി. ശേഷം അയാൾ വന്ന് രക്തസാക്ഷിത്വം വഹിച്ചയാൾക്ക് അനുവാദം നൽകി. ശേഷം അയാൾ എന്റെ അടുത്ത് വന്ന് പറഞ്ഞു: താങ്കൾ മടങ്ങിപ്പോവുക, താങ്കൾക്ക് ഇതുവരെ സമയമായിട്ടില്ല. നേരം പുലർന്നപ്പോൾ ത്വൽഹ(റ) ഈ വിവരം ജനങ്ങളോട് പറയുകയും ജനങ്ങൾ അത്ഭുതപ്പെടുകയും ചെയ്തു. ആ വാർത്ത റസൂൽ(സ)യുടെ അടുത്തെത്തി. അവർ റസൂൽ(സ)ക്ക് സംഭവം വിവരിച്ചുകൊടുത്തു. റസൂൽ(സ) ചോദിച്ചു: "അതിൽ നിങ്ങളെ അത്ഭുതപ്പെടുത്തിയത് എന്താണ്?" അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവരിലൊരുത്തൻ കൂടുതൽ പരിശ്രമിക്കുന്നവനായിരുന്നു. ശേഷം അയാൾ രക്തസാക്ഷിയായി. എന്നാൽ മറ്റെയാൾ അദ്ദേഹത്തിനു മുമ്പ് സ്വർഗ്ഗത്തിൽ പ്രവേശിച്ചിരിക്കുന്നു. റസൂൽ(സ) പറഞ്ഞു: "അയാൾ മറ്റെയാൾക്ക് ശേഷം ഒരു വർഷം ജീവിച്ചില്ലേ." അവർ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "അയാൾ റമളാനെ വരവേൽക്കുകയും നോമ്പനുഷ്ടിക്കുകയും ചെയ്തില്ലേ, മാത്രമല്ല ഒരു വർഷത്തിനുള്ളിൽ ധാരാളം പ്രാവശ്യം നമസ്കരിക്കുകയും ചെയ്തില്ലേ." അവർ പറഞ്ഞു: അതെ. റസൂൽ(സ) പറഞ്ഞു: "അവർക്കിടയിലെ വ്യത്യാസം ആകാശഭൂമികൾക്കിടയിലെ ദൂരത്തേക്കാൾ ഏറെയാണ്." (ജ)', 'طَلْحَةَ بْنِ عُبَيْدِ اللهِ', 'ത്വൽഹതുബ്നു ഉബൈദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 863, 864, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أَبِي رَزِينٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الرُّؤْيَا عَلَى رِجْلِ طَائِرٍ مَا لَمْ تُعْبَرْ، فَإِذَا عُبِرَتْ وَقَعَتْ". قَالَ: "وَالرُّؤْيَا جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنَ النُّبُوَّةِ". قَالَ: وَأَحْسِبُهُ قَالَ: "لَا يَقُصُّهَا إِلَّا عَلَى وَادٍّ أَوْ ذِي رَأْيٍ". (د,ت,جه)', 'അബൂറസീൻ(റ): നബി(സ) പറഞ്ഞു: "സ്വപനം വ്യാഖ്യാനിക്കപ്പെടാത്ത സമയത്തോളം പക്ഷിയുടെ കാലിന്മേലാണ് (ഒന്നും സംഭവിക്കില്ല). വ്യാഖ്യാനിക്കപ്പെട്ടാൽ അത് സംഭവിക്കും." നബി(സ) പറഞ്ഞു: "സ്വപ്നം നുബുവ്വതിന്റെ നാൽപത്തിയാറിൽ ഒരു അംശമാണ്." നബി(സ) പറയുന്നു: "സ്വപ്നം ബുദ്ധിയുള്ളവരോടോ സ്നേഹിക്കുന്നവരോടോ അല്ലാതെ വിവരിക്കരുത്." (ദ,തു,ജ)', 'أَبِي رَزِينٍ', 'അബൂറസീൻ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 864, 864, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الرُّؤْيَا ثَلَاثٌ: فَرُؤْيَا حَقٌّ، وَرُؤْيَا يُحَدِّثُ بِهَا الرَّجُلُ نَفْسَهُ، وَرُؤْيَا تَحْزِينٌ مِنَ الشَّيْطَانِ. فَمَنْ رَأَى مَا يَكْرَهُ فَلْيَقُمْ فَلْيُصَلِّ". وَكَانَ يَقُولُ: "يُعْجِبُنِي الْقَيْدُ، وَأَكْرَهُ الْغُلَّ، الْقَيْدُ: ثَبَاتٌ فِي الدِّينِ". وَكَانَ يَقُولُ: "مَنْ رَآنِي فَإِنِّي أَنَا هُوَ، فَإِنَّهُ لَيْسَ لِلشَّيْطَانِ أَنْ يَتَمَثَّلَ بِي". وَكَانَ يَقُولُ: "لَا تُقَصُّ الرُّؤْيَا إِلَّا عَلَى عَالِمٍ أَوْ نَاصِحٍ". حَسَنٌ صَحِيحٌ. (ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "സ്വപ്നം മൂന്ന് ഇനമാണ്: സത്യമായ സ്വപ്നം, ഒരാൾ സ്വന്തത്തോട് സംസാരിക്കുന്ന സ്വപ്നം, പിശാചിന്റെ ഭാഗത്തുനിന്നുള്ള ദുഃഖിപ്പിക്കുന്ന സ്വപ്നം. അതിനാൽ ആരെങ്കിലും താൻ വെറുക്കുന്ന വല്ലതും കണ്ടാൽ എഴുന്നേറ്റ് നമസ്കരിച്ച് കൊള്ളുക." റസൂൽ(സ) പറയാറുണ്ടായിരുന്നു: "എനിക്ക് സ്ഥിരമായിരിക്കലാണ് ഇഷ്ടം. ബന്ധനസ്ഥനാവലിനെ ഞാൻ വെറുക്കുന്നു. സ്ഥിരമായിരിക്കൽ എന്നാൽ മതത്തിൽ സ്ഥിരമാകലാണ്." നബി(സ) പറയാറുണ്ടായിരുന്നു: "ഒരുത്തൻ എന്നെ സ്വപ്നത്തിൽ ദർശിച്ചാൽ ഞാൻ തന്നെയാണ് അത്. കാരണം പിശാചിന് എന്റെ രൂപം പ്രാപിക്കാൻ സാധ്യമല്ല." റസൂൽ(സ) പറയാറുണ്ടായിരുന്നു: "ഒരു സദുപദേശകനോടോ, ജ്ഞാനിയോടോ അല്ലാതെ സ്വപ്നം വിവരിക്കപ്പെടരുത്." (തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 864, 864, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي رَأَيْتُ رَأْسِي ضُرِبَ، فَرَأَيْتُهُ يَتَدَهْدَهُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَعْمِدُ الشَّيْطَانُ إِلَى أَحَدِكُمْ فَيَتَهَوَّلُ لَهُ، ثُمَّ يَغْدُو يُخْبِرُ النَّاسَ". (جه)', 'അബൂഹുറൈറ(റ): ഒരാൾ നബി(സ)യുടെ അടുത്തേക്ക് വന്ന് പറഞ്ഞു: എന്റെ ശിരസ്സിനു മുകളിൽ അടിക്കപ്പെടുന്നതായും അത് പൊട്ടുന്നതായും ഞാൻ സ്വപ്നം കണ്ടു. റസൂൽ(സ) പറഞ്ഞു: "പിശാച് നിങ്ങളിലൊരുത്തന്റെ അടുത്തുവന്ന് അവനെ പേടിപ്പിക്കും. പിന്നെ അവൻ അത് ജനങ്ങളെ അറിയിക്കും." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 865, 865, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ وَهُوَ يَخْطُبُ، فَقَالَ: يَا رَسُولَ اللهِ، رَأَيْتُ الْبَارِحَةَ – فِيمَا يَرَى النَّائِمُ – كَأَنَّ عُنُقِي ضُرِبَتْ، وَسَقَطَ رَأْسِي، فَاتَّبَعْتُهُ فَأَخَذْتُهُ فَأَعَدْتُهُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا لَعِبَ الشَّيْطَانُ بِأَحَدِكُمْ فِي مَنَامِهِ فَلَا يُحَدِّثَنَّ بِهِ النَّاسَ". (م)', 'ജാബിർ(റ): ഖുതുബ ഓതിക്കൊണ്ടിരിക്കെ ഒരാൾ നബി(സ)യുടെ സന്നിധിയിൽ വന്ന് പറഞ്ഞു: റസൂലേ, എന്റെ കഴുത്തറുക്കപ്പെടുന്നതായും തല വീഴുന്നതായും ഞാൻ അതിനെ പിന്തുടർന്ന് അത് തിരികെ വെക്കുന്നതായും ഇന്നലെ രാത്രി ഞാൻ സ്വപ്നം കണ്ടു. റസൂൽ(സ) പറഞ്ഞു: "പിശാച് നിങ്ങളിലൊരുത്തനെ സ്വപ്നത്തിൽ ശല്യപ്പെടുത്തിയാൽ അത് മറ്റു ജനങ്ങളോട് പറയരുത്." (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 865, 865, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا حَلَمَ أَحَدُكُمْ فَلَا يُخْبِرِ النَّاسَ بِتَلَعُّبِ الشَّيْطَانِ بِهِ فِي الْمَنَامِ". (م,جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ ആരെങ്കിലും ദുസ്വപ്നം കണ്ടാൽ പിശാച് തന്നെ ഉറക്കത്തിൽ ശല്യപ്പെടുത്തിയത് അവൻ ജനങ്ങളെ അറിയിക്കരുത്." (മു,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 865, 865, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، رَأَيْتُ فِي الْمَنَامِ كَأَنَّ رَأْسِي ضُرِبَ فَتَدَحْرَجَ، فَاشْتَدَدْتُ عَلَى أَثَرِهِ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ [لِلْأَعْرَابِيِّ]: "لَا تُحَدِّثِ النَّاسَ بِتَلَعُّبِ الشَّيْطَانِ بِكَ فِي مَنَامِكَ". وَقَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ فَقَالَ: "لَا يُحَدِّثَنَّ أَحَدُكُمْ بِتَلَعُّبِ الشَّيْطَانِ بِهِ فِي مَنَامِهِ". (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഒരു അഅ്റാബി നബി(സ)യുടെ അടുത്തുവന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ തല വെട്ടപ്പെടുന്നതായും അത് ഉരുളുന്നതായും ഞാൻ അതിനെ പിന്തുടരുന്നതായും ഞാൻ സ്വപ്നം കണ്ടു. നബി(സ) അഅ്റാബിയോട് പറഞ്ഞു: "സ്വപ്നത്തിൽ പിശാച് ശല്യപ്പെടുത്തുന്നതിനെ സംബദ്ധിച്ച് നീ ജനങ്ങളോട് സംസാരിക്കരുത്." ജാബിർ(റ) പറഞ്ഞു: നബി(സ) ഇപ്രകാരം പ്രസംഗിക്കുന്നതായി ഞാൻ കേട്ടു: "സ്വപ്നത്തിൽ പിശാച് ശല്യപ്പെടുത്തിയതിനെക്കുറിച്ച് നിങ്ങളാരും സംസാരിക്കരുത്." (മു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], 'لِلْأَعْرَابِيِّ', null, 865, 865, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ كَذَبَ فِي حُلْمِهِ كُلِّفَ يَوْمَ الْقِيَامَةِ عَقْدَ شَعِيرَةٍ". حَسَنٌ. (ت)', 'അലി(റ): നബി(സ) പറഞ്ഞു: "സ്വപ്നം കണ്ടുവെന്ന് ഒരുത്തൻ നുണ പറഞ്ഞാൽ അന്ത്യനാളിൽ ധാന്യം കെട്ടിയിടാൻ അവൻ നിർബന്ധിക്കപ്പെടുന്നതാണ്." (തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 865, 866, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ تَحَلَّمَ بِحُلْمٍ لَمْ يَرَهُ، كُلِّفَ أَنْ يَعْقِدَ بَيْنَ شَعِيرَتَيْنِ وَلَنْ يَفْعَلَ، وَمَنِ اسْتَمَعَ إِلَى حَدِيثِ قَوْمٍ، وَهُمْ لَهُ كَارِهُونَ، أَوْ يَفِرُّونَ مِنْهُ، صُبَّ فِي أُذُنِهِ الْآنُكُ يَوْمَ الْقِيَامَةِ، وَمَنْ صَوَّرَ صُورَةً عُذِّبَ، وَكُلِّفَ أَنْ يَنْفُخَ فِيهَا، وَلَيْسَ بِنَافِخٍ". (خ,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും താൻ സ്വപ്നം കണ്ടുവെന്ന് നുണ പറഞ്ഞാൽ രണ്ട് ധാന്യങ്ങൾ തമ്മിൽ കൂട്ടിക്കെട്ടാൻ അവൻ നിർബന്ധിക്കപ്പെടും, അത് അവന് സാധ്യമാവുകയില്ല. മറ്റുള്ളവർ അറിയരുതെന്ന് ആഗ്രഹിക്കുന്നവന്റെ സംസാരം ഒരുത്തൻ കട്ടുകേട്ടാൽ അന്ത്യനാളിൽ അവന്റെ ചെവിയിൽ ഈയം ഒഴിക്കപ്പെടുന്നതാണ്. ആരെങ്കിലും ഒരു രൂപമുണ്ടാക്കിയാൽ അവൻ ശിക്ഷിക്കപ്പെടുകയും അതിൽ ആത്മാവിനെ ഊതാൻ നിർബന്ധിക്കപ്പെടുകയും ചെയ്യും. എന്നാൽ അവനത് സാധിക്കുകയില്ല." (ബു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 866, 866, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَحَلَّمَ حُلْمًا كَاذِبًا كُلِّفَ أَنْ يَعْقِدَ بَيْنَ شَعِيرَتَيْنِ، وَيُعَذَّبُ عَلَى ذَلِكَ". (خ,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ആരെങ്കിലും വല്ല കള്ളസ്വപ്നവും കണ്ടുവെന്ന് പറഞ്ഞാൽ രണ്ട് ധാന്യങ്ങളെ കൂട്ടിക്കെട്ടാൻ അവൻ നിർബന്ധിക്കപ്പെടുകയും അതിന്റെ പേരിൽ അവൻ ശിക്ഷിക്കപ്പെടുകയും ചെയ്യുന്നതാണ്." (ബു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 866, 866, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ مِنْ أَفْرَى الْفِرَى أَنْ يُرِيَ عَيْنَهُ مَا لَمْ تَرَ". (خ)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "തന്റെ കണ്ണ് കണ്ടിട്ടില്ലാത്ത കാര്യങ്ങൾ അതിന് കാണിക്കലാണ് (കണ്ടെന്ന് പറയലാണ്) അപവാദങ്ങളിൽ ഏറ്റവും വലിയ അപവാദം." (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 866, 866, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
